(()=>{'use strict';
const $=id=>document.getElementById(id);
const sceneData={"S01":{"id":"S01","title":"A village that forgot the war","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Bellhaven was the first stop on the long road to Sarovar. The market town was renowned throughout the kingdom for its alchemists and master armourers. Travelers came from distant provinces seeking enchanted weapons, restorative elixirs, and equipment that could withstand even the most treacherous wilderness."},{"who":"NARRATION","mood":"neutral","text":"For Isa, Rei, and Athena, the purpose of their visit was considerably less glamorous. They needed rations, medical supplies, stronger equipment, and a reliable map before beginning the most dangerous leg of their journey."},{"who":"NARRATION","mood":"neutral","text":"Since the war between the Shadow Archmage and the Moon Goddess, the world had grown increasingly unstable. The Archmage’s assault had fractured the moon itself, leaving the Goddess’s power diminished and the kingdom vulnerable to forces long held at bay."},{"who":"NARRATION","mood":"neutral","text":"Although the fighting had subsided, its consequences remained. Strange magical disturbances had begun appearing across the land, and travelers whispered of roads that changed overnight, missing caravans, and creatures behaving unnaturally."},{"who":"NARRATION","mood":"neutral","text":"Yet Bellhaven seemed determined to carry on as though nothing had happened."},{"who":"NARRATION","mood":"neutral","text":"Sunlight spilled across red-tiled rooftops. Merchants called out their prices beneath colorful awnings, the smell of fresh bread drifted through the square, and children chased one another around the fountain. High above the cheerful town, barely visible against the morning sky, hung the thin scar of the moon’s fracture."},{"who":"ISA","mood":"neutral","text":"It's strange, isn't it? Everything looks so normal."},{"who":"REI","mood":"neutral","text":"People still need to eat. Even with a fractured moon."},{"who":"ISA","mood":"sad","text":"You know what I mean."},{"who":"REI","mood":"neutral","text":"I do. But the Archmage hasn't stopped simply because the fighting has."},{"who":"ISA","mood":"neutral","text":"Which is why we need to get to Sarovar."},{"who":"REI","mood":"neutral","text":"And why we need to get there alive. Four days of rations, healing supplies, protective equipment, and a trustworthy map. Preferably before you spend all our gold."},{"who":"ISA","mood":"excited","text":"Oh! Speaking of spending gold—REI! LOOK AT THOSE LITTLE MUSHROOM CAKES!"},{"who":"REI","mood":"annoyed","text":"We've been here for approximately thirty seconds."},{"who":"ISA","mood":"excited","text":"AND THE CANDIED PEARS!"},{"who":"REI","mood":"smug","text":"There goes the expedition budget."},{"who":"ATHENA","mood":"happy","text":"WOOF!"},{"who":"ISA","mood":"happy","text":"See? Athena agrees with me."},{"who":"REI","mood":"neutral","text":"Athena is looking at the butcher's stall."},{"who":"REI","mood":"neutral","text":"We have an enormous dog. She is currently standing on my foot."},{"who":"ISA","mood":"annoyed","text":"She is allowed to appreciate the market."},{"who":"REI","mood":"smug","text":"That's what you said before Athena started sleeping in our bed."},{"who":"ISA","mood":"mad","text":"ATHENA NEEDED A HOME."},{"who":"ATHENA","mood":"happy","text":"WOOF!"},{"who":"REI","mood":"laugh","text":"The accused has offered no defense."},{"who":"ISA","mood":"laugh","text":"She doesn't need one. She has an excellent lawyer."},{"who":"NARRATION","mood":"neutral","text":"Athena pulled them toward a butcher's stall, where sausages dangled at precisely muzzle height. Rei gave the leash a gentle tug."},{"who":"REI","mood":"neutral","text":"No, Athena."},{"who":"NARRATION","mood":"neutral","text":"Athena sat at once, her gaze fixed on the meat."},{"who":"ISA","mood":"happy","text":"Look at her listening!"},{"who":"REI","mood":"smug","text":"That's not obedience. It's a negotiation. She learned it from you."},{"who":"ISA","mood":"annoyed","text":"I'm going to start charging you per insult."},{"who":"REI","mood":"laugh","text":"I'd bankrupt us by noon."}],"flags":{},"to":"S02"},"S02":{"id":"S02","title":"What we are here for","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"They paused by the square's stone fountain. Rei unfolded the journal where he had recorded the routes north, the reports of missing travelers, and the fragments of lunar history that might lead them toward Sarovar."},{"who":"REI","mood":"neutral","text":"Food for four days, water, healing supplies, and a reliable road north. After that, we leave before dark."},{"who":"ISA","mood":"neutral","text":"And ask about strange magic. The Goddess said the fracture was spreading. If anyone has seen it, it might be here."},{"who":"REI","mood":"happy","text":"Yes. That's why I brought the clever one."},{"who":"ISA","mood":"smug","text":"You're referring to me, obviously."},{"who":"REI","mood":"smug","text":"Athena has been very perceptive today."},{"who":"ISA","mood":"mad","text":"REI."},{"who":"REI","mood":"laugh","text":"There she is."},{"who":"NARRATION","mood":"neutral","text":"Isa glanced up at the faint broken moon. Her smile softened."},{"who":"ISA","mood":"sad","text":"She was trying so hard not to sound afraid when she called us. I've never heard her like that."},{"who":"REI","mood":"neutral","text":"I know."},{"who":"ISA","mood":"neutral","text":"What if we get there too late?"},{"who":"REI","mood":"neutral","text":"Then we get there as quickly as possible. Worry is useful only if it tells us what to do next."},{"who":"ISA","mood":"annoyed","text":"That is the least comforting thing anyone has ever said to me."},{"who":"REI","mood":"happy","text":"I was saving my comforting speech for the journey."},{"who":"ISA","mood":"smug","text":"Does it have jokes?"},{"who":"REI","mood":"smug","text":"Several. You won't like them."}],"flags":{},"to":"S03"},"S03":{"id":"S03","title":"Tobin and Biscuit","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"A sharp crash interrupted them. Near the fountain, a market vendor’s small handcart lurched sideways. A leather strap trapped a brown terrier’s paw beneath the wheel. A freckled boy wearing a patched cap and green scarf knelt beside the cart, afraid to pull the strap any tighter."},{"who":"TOBIN","mood":"scared","text":"Biscuit! Please, somebody help him!"},{"who":"ISA","mood":"scared","text":"Rei, lift the cart frame. Slowly. I’ve got his paw."},{"who":"REI","mood":"neutral","text":"On your signal."},{"who":"NARRATION","mood":"neutral","text":"Rei lifted the market vendor’s cart just enough for Isa to free the trapped paw. The terrier trembled, but her moonlight magic eased the swelling. Biscuit took two careful steps, then jumped up to lick Isa’s cheek."},{"who":"TOBIN","mood":"happy","text":"Biscuit! You can walk! Thank you so much!"},{"who":"ISA","mood":"cry","text":"There you go, sweetheart. You’re all right."},{"who":"REI","mood":"smug","text":"At that rate, Biscuit is going to lick every inch of your face."},{"who":"ISA","mood":"laugh","text":"He can have as many kisses as he wants."},{"who":"NARRATION","mood":"neutral","text":"The boy introduced himself as Tobin and hugged Biscuit close. A woman hurried over from the vegetable stall, calling his name. Tobin ran to his mother and explained what had happened. Relieved that both were safe, she thanked Isa and Rei, then offered them a loaf of bread wrapped in linen. Athena watched the loaf with considerable interest."},{"who":"MOTHER","mood":"happy","text":"Thank you for helping my Tobin and his Biscuit. I don’t know what I would have done if you hadn’t been here."}],"flags":{},"to":"D01"},"D01":{"id":"D01","title":"How does Isa respond to Tobin’s mother?","bg":"VILLAGE","kind":"choice","options":[{"label":"Accept the bread graciously","lines":[{"who":"ISA","mood":"happy","text":"Thank you. We’ll share it on the road."},{"who":"MOTHER","mood":"happy","text":"Tobin and Biscuit would insist. You brought our family a little peace today."},{"who":"REI","mood":"smug","text":"And Athena has already volunteered to carry it."},{"who":"ISA","mood":"annoyed","text":"She’s volunteering to eat it. There’s a difference."}],"flags":{"bread":true,"family_trust":true,"supplies_delta":1},"to":"S04","requires":[]},{"label":"Refuse; they need it more","lines":[{"who":"ISA","mood":"neutral","text":"Please keep it for Tobin and Biscuit. Seeing him walking is enough."},{"who":"MOTHER","mood":"neutral","text":"Then take a warning instead. Men are stopping wagons north of town. Be careful with anyone selling shortcuts."},{"who":"REI","mood":"neutral","text":"We will. Thank you."}],"flags":{"road_warning":true,"family_trust":true},"to":"S04","requires":[]},{"label":"Ask about trouble in town","lines":[{"who":"ISA","mood":"neutral","text":"Actually, have people been behaving strangely around the market?"},{"who":"MOTHER","mood":"neutral","text":"Men have been demanding protection payments from shopkeepers. None of us has seen them protect anything."},{"who":"REI","mood":"neutral","text":"Have you told the guards?"},{"who":"MOTHER","mood":"neutral","text":"We did. But the captain says he needs proof that will hold up."}],"flags":{"protection_rumor":true,"family_trust":true},"to":"S04","requires":[]}],"lines":[]},"S04":{"id":"S04","title":"Four invitations","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Back at the fountain, Bellhaven opened around them like a page in a storybook. An elderly map seller with a flamboyant feathered hat beckoned from his stall. A short walk away, a brightly decorated shop released a puff of electric-blue smoke, followed by faint music. Vendors argued over prices in the market. Athena had her nose aimed at a narrow alley beside the bakery."},{"who":"ISA","mood":"excited","text":"A map stall, an alchemy shop, fresh provisions, and whatever Athena has discovered. We could get so much done!"},{"who":"REI","mood":"neutral","text":"We could also accomplish nothing efficiently if we chase all four at once."},{"who":"ISA","mood":"smug","text":"Your pessimism is exhausting."},{"who":"REI","mood":"laugh","text":"My realism has kept you from buying six decorative cabbages."},{"who":"ISA","mood":"annoyed","text":"THEY WERE BEAUTIFUL CABBAGES."}],"flags":{},"to":"D02"},"D02":{"id":"D02","title":"Pick the main route","bg":"VILLAGE","kind":"choice","options":[{"label":"Find a trustworthy map","lines":[{"who":"ISA","mood":"neutral","text":"Let's start with directions. No amount of cake will help if we get lost."},{"who":"REI","mood":"happy","text":"A devastatingly sensible sentence. I should write it down."}],"flags":{"route":"A"},"to":"A01","requires":[]},{"label":"Enter the glittering alchemy shop","lines":[{"who":"ISA","mood":"excited","text":"I need to know why that shop has stage lights."},{"who":"REI","mood":"annoyed","text":"We are almost certainly going to regret this."},{"who":"ISA","mood":"smug","text":"Then we'll regret it together."}],"flags":{"route":"B"},"to":"B01","requires":[]},{"label":"Follow Athena and ask around the marketplace","lines":[{"who":"ATHENA","mood":"angry","text":"Grrr."},{"who":"REI","mood":"neutral","text":"That's not her hungry growl. Something's frightened her."},{"who":"ISA","mood":"neutral","text":"Then let's see what it is."}],"flags":{"route":"C"},"to":"C01","requires":[]}],"lines":[]},"A01":{"id":"A01","title":"A kindly old gentleman","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The cartographer's stall was an immaculate little island in the market's noise. Brass weights pinned maps flat; leather atlases stood in careful rows. A round elderly man with white whiskers, wire spectacles, and a burgundy hat whose feather was taller than his head beamed at the newcomers."},{"who":"VENDOR","mood":"neutral","text":"Travelers! And a magnificent dog! Welcome, welcome. I have maps for every conceivable journey, including one waterfall that I have yet to discover myself."},{"who":"ISA","mood":"happy","text":"We're going toward Sarovar."},{"who":"VENDOR","mood":"nervous","text":"Sarovar? Oh, a very unfortunate road, these days."},{"who":"REI","mood":"neutral","text":"The northern pilgrim route?"},{"who":"VENDOR","mood":"neutral","text":"Dangerous, dreadful, terribly inconvenient. But I happen to have the Willowpass Shortcut. Half the distance, none of the unpleasantness. Twelve coins, with a compass included."},{"who":"ISA","mood":"confused","text":"Half the distance?"},{"who":"REI","mood":"neutral","text":"That's a remarkable change to a road that's been used for centuries."},{"who":"VENDOR","mood":"neutral","text":"Forty years of experience, young man. The world rewards those who know where to look."}],"flags":{},"to":"D03"},"D03":{"id":"D03","title":"First response to the shortcut","bg":"VILLAGE","kind":"choice","options":[{"label":"Inspect the geography","lines":[{"who":"REI","mood":"neutral","text":"May I see the survey?"},{"who":"VENDOR","mood":"neutral","text":"Of course, of course."},{"who":"ISA","mood":"smug","text":"He's going to make you regret that."}],"flags":{"map_inspected":true},"to":"A02","requires":[]},{"label":"Ask who found this route","lines":[{"who":"ISA","mood":"neutral","text":"Who surveyed Willowpass? We could ask how recently they traveled it."},{"who":"VENDOR","mood":"nervous","text":"An associate. Very private gentleman."},{"who":"REI","mood":"smug","text":"Private enough not to have a name?"}],"flags":{"surveyor_questioned":true},"to":"A03","requires":[]},{"label":"Trust him and buy it","lines":[{"who":"ISA","mood":"neutral","text":"A shorter road could give us precious time."},{"who":"REI","mood":"neutral","text":"It could. I would prefer to compare it against the terrain as we go."},{"who":"VENDOR","mood":"smug","text":"An excellent decision!"}],"flags":{"false_map_owned":true,"coins_delta":-12},"to":"A04","requires":[]},{"label":"Decline and leave","lines":[{"who":"ISA","mood":"neutral","text":"Thank you. We'll ask the people who actually travel the roads first."},{"who":"VENDOR","mood":"neutral","text":"As you wish!"},{"who":"REI","mood":"happy","text":"An excellent plan."}],"flags":{"vendor_declined":true},"to":"A05","requires":[]}],"lines":[]},"A02":{"id":"A02","title":"A bridge through solid rock","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei tilted the map into the sunlight. His finger moved to the inked road beneath a ridge of mountains."},{"who":"REI","mood":"confused","text":"You've marked the bridge west of the river, where the river enters the cliff. On the official survey the bridge is east, below the bend."},{"who":"VENDOR","mood":"nervous","text":"Perhaps the river changed direction!"},{"who":"ISA","mood":"neutral","text":"Through a mountain?"},{"who":"VENDOR","mood":"nervous","text":"Geography is terribly unpredictable."},{"who":"REI","mood":"smug","text":"In my experience, mountains are relatively dependable."},{"who":"ISA","mood":"laugh","text":"That's a new sentence for your journal."},{"who":"NARRATION","mood":"neutral","text":"The ink across the road was a colder blue than the rest, and near the false bridge stood three hooked marks around a ring."},{"who":"ISA","mood":"neutral","text":"Someone repainted the road. But that only tells us it's altered, not why."},{"who":"REI","mood":"happy","text":"Exactly."},{"who":"VENDOR","mood":"nervous","text":"It is merely an updated edition."}],"flags":{},"to":"D04"},"D04":{"id":"D04","title":"Handle the discrepancy","bg":"VILLAGE","kind":"choice","options":[{"label":"Buy it as bait","lines":[{"who":"ISA","mood":"happy","text":"Then it's a bargain. We'll take it."},{"who":"REI","mood":"confused","text":"We will?"},{"who":"ISA","mood":"smug","text":"Yes, Rei. Do keep up."},{"who":"NARRATION","mood":"neutral","text":"Only outside the stall does she whisper, \"I want to know who he tells.\""},{"who":"REI","mood":"laugh","text":"You were wonderful. And terrifying."}],"flags":{"false_map_owned":true,"vendor_suspected":true,"coins_delta":-12},"to":"A06","requires":[]},{"label":"Accuse him publicly","lines":[{"who":"ISA","mood":"mad","text":"WHY ARE YOU SELLING PEOPLE ROADS THAT DON'T EXIST?"},{"who":"VENDOR","mood":"nervous","text":"My dear, you're making a scene!"},{"who":"REI","mood":"neutral","text":"We have evidence of alteration. Let's not claim more than we can prove."},{"who":"NARRATION","mood":"neutral","text":"A man across the square slips away at the accusation."}],"flags":{"vendor_alerted":true,"vendor_suspected":true},"to":"A07","requires":[]},{"label":"Memorize the symbol and leave quietly","lines":[{"who":"ISA","mood":"neutral","text":"We'll think about it."},{"who":"NARRATION","mood":"neutral","text":"Rei sketches the symbol in his journal outside."},{"who":"REI","mood":"neutral","text":"Let's compare it to the shipping marks at the guild records."}],"flags":{"symbol_copied":true,"vendor_suspected":true},"to":"A08","requires":[]}],"lines":[]},"A03":{"id":"A03","title":"The surveyor who retired","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"When pressed, the cartographer finally offered the name Master Aldren. At a neighboring stall, an elderly trader laughed in disbelief. TRADER [neutral]: \"Aldren? He retired ten years ago. Lives south with his grandchildren. Hasn't climbed a mountain since his knee went bad.\""},{"who":"ISA","mood":"neutral","text":"Maybe someone used his charts."},{"who":"REI","mood":"neutral","text":"That's possible. The merchant claimed a new survey by Aldren, though. Those aren't the same thing."},{"who":"ISA","mood":"smug","text":"Then we ask him again. Politely, first."},{"who":"REI","mood":"laugh","text":"I'm glad you added 'first.'"}],"flags":{"surveyor_lie":true},"to":"A09"},"A04":{"id":"A04","title":"The Willowpass road","bg":"ROAD","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"By mid-afternoon, the village faded behind the hills. The Willowpass Shortcut looked picturesque enough: wildflowers, an old fence, and a path threading between two low ridges. What it lacked were wheel tracks, fresh hoofprints, or any sign of the busy caravans the merchant had described."},{"who":"ISA","mood":"neutral","text":"I do like the quiet."},{"who":"REI","mood":"neutral","text":"I don't. A recently opened trade road should show use. This one doesn't."},{"who":"ISA","mood":"annoyed","text":"You could have said that earlier."},{"who":"REI","mood":"smug","text":"I believe I suggested we verify the map."},{"who":"ISA","mood":"mad","text":"I KNOW WHAT YOU SUGGESTED."},{"who":"ATHENA","mood":"angry","text":"Grrrr."},{"who":"NARRATION","mood":"neutral","text":"Athena froze. Rei spotted a line stretched between two trees. A tripwire. Farther ahead, a shadow shifted above the rocks."},{"who":"REI","mood":"neutral","text":"A trap. Now we know why the road exists."}],"flags":{"trap_confirmed":true},"to":"A10"},"A05":{"id":"A05","title":"Walk away from the stall","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Outside the map stall, Isa and Rei asked a drover which roads were actually safe. He described the long northern trade road and admitted the bandits had become bolder, but he had never heard of Willowpass."},{"who":"ISA","mood":"neutral","text":"Then we'll take the route someone can actually describe."},{"who":"REI","mood":"neutral","text":"Wise. We can still ask the guard captain to investigate that merchant if we collect corroboration."},{"who":"ISA","mood":"smug","text":"Or we can leave with our money and our limbs."},{"who":"REI","mood":"laugh","text":"An underrated collection."}],"flags":{"reliable_directions":true},"to":"A11"},"A06":{"id":"A06","title":"The courier","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Isa and Rei sat beside the fountain as though planning their journey. A thin, hooded messenger emerged from a side passage and approached the map stall. The vendor handed him a folded slip."},{"who":"ISA","mood":"neutral","text":"There. He's telling someone about us."},{"who":"REI","mood":"neutral","text":"Maybe. We need the message or its destination."},{"who":"ISA","mood":"smug","text":"I can get it."},{"who":"REI","mood":"smug","text":"I have never doubted your ability to make a memorable distraction."},{"who":"ISA","mood":"annoyed","text":"I AM SUBTLE WHEN I WANT TO BE."},{"who":"REI","mood":"laugh","text":"That was beautifully subtle."}],"flags":{},"to":"D05"},"A07":{"id":"A07","title":"The watcher flees","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The crowd turned toward Isa's accusation; across the square, a man in a patched hood hurried toward the warehouses, looking back once. Rei touched Isa's elbow."},{"who":"REI","mood":"neutral","text":"That man was watching the stall, not the goods."},{"who":"ISA","mood":"neutral","text":"And he started moving when I raised my voice."},{"who":"REI","mood":"neutral","text":"Suggestive, but not conclusive."},{"who":"ISA","mood":"smug","text":"I know, I know. Evidence. You're going to say it until we both turn into fossils."},{"who":"REI","mood":"happy","text":"It's a good word."},{"who":"NARRATION","mood":"neutral","text":"As he slipped past the cobbler, the hooded watcher accepted a folded note from a second man beside the cartographer’s stall. He tucked it into his belt and hurried toward the western stables."}],"flags":{"messenger_spotted":true},"to":"D05"},"A08":{"id":"A08","title":"Guild marks","bg":"ARCHIVE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"In the town archive, Rei and Isa compared his sketch with old shipping seals. The pattern matched a mark used by a defunct freight consortium, but the registry described its recent use as unauthorized."},{"who":"REI","mood":"neutral","text":"Someone revived an old commercial mark. It might be counterfeit."},{"who":"ISA","mood":"neutral","text":"The merchant's shortcut leads to a crossing nobody knows, and he's using a mark he can't explain. We need to see what gets shipped under it."},{"who":"REI","mood":"happy","text":"Now you're thinking like an investigator."},{"who":"ISA","mood":"annoyed","text":"I HAVE BEEN THINKING LIKE AN INVESTIGATOR."},{"who":"REI","mood":"laugh","text":"Quite loudly."}],"flags":{"shipping_mark_lead":true},"to":"A13"},"A09":{"id":"A09","title":"A second conversation","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The vendor's smile wavered when Isa returned with Aldren's name."},{"who":"ISA","mood":"neutral","text":"Master Aldren retired a decade ago. Who surveyed your road?"},{"who":"VENDOR","mood":"nervous","text":"His... students. Of course. I was simplifying."},{"who":"REI","mood":"neutral","text":"Then show us a dated survey."},{"who":"VENDOR","mood":"nervous","text":"I'm afraid I left it at home."},{"who":"ISA","mood":"smug","text":"I suspect you leave a lot of things at home. The truth, for example."},{"who":"NARRATION","mood":"neutral","text":"The vendor’s gaze flicked toward the alley. A young courier in a patched hood emerged, accepted a folded note from beneath the map display, and turned toward the western stables. Rei waited until the courier was out of earshot."},{"who":"REI","mood":"neutral","text":"Now we have someone to follow. Whatever this is, we need the note or its destination."}],"flags":{"vendor_suspected":true},"to":"D05"},"D05":{"id":"D05","title":"Courier response (from A06/A07/A09)","bg":"VILLAGE","kind":"choice","options":[{"label":"Follow him through the alley","lines":[{"who":"REI","mood":"neutral","text":"Don't crowd him. We need to know where he's going."},{"who":"ISA","mood":"smug","text":"You mean don't shout 'STOP, CRIMINAL' across the market?"},{"who":"REI","mood":"laugh","text":"Precisely."}],"flags":{},"to":"A12","requires":[]},{"label":"Intercept the folded note","lines":[{"who":"ISA","mood":"happy","text":"Excuse me, you've dropped something!"},{"who":"NARRATION","mood":"neutral","text":"As the messenger looked down, Rei levitated the folded note from his satchel. It described two spellcasters, a dog, and a collection at the Willowpass crossing."},{"who":"ISA","mood":"mad","text":"They've priced us like cargo."},{"who":"REI","mood":"neutral","text":"Now we can prove a link to the ambush."}],"flags":{"note_seized":true,"trap_confirmed":true},"to":"A24","requires":[]},{"label":"Ask the town guard to help","lines":[{"who":"ISA","mood":"neutral","text":"We shouldn't risk losing him. Let's ask the guards to watch the passage."},{"who":"REI","mood":"neutral","text":"They'll need something concrete to justify an arrest. We can at least request surveillance."}],"flags":{"guard_contacted":true},"to":"A16","requires":[]}],"lines":[]},"A10":{"id":"A10","title":"Ambush at Willowpass","bg":"ROAD","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Three men emerged from above the path. Behind them stood a scarred leader in a red scarf, smiling through several missing teeth. The bandits had the high ground. A second tripwire cut off the easiest escape."},{"who":"BANDIT","mood":"normal","text":"Lovely road, isn't it? Shame about the toll. Hand over your gold and your bags."},{"who":"ISA","mood":"angry","text":"You arranged this with the map seller!"},{"who":"BANDIT","mood":"normal","text":"Maybe he sends us the occasional customer. What's it to you?"},{"who":"REI","mood":"neutral","text":"Enough to tell us where to aim."},{"who":"ISA","mood":"smug","text":"You planned an ambush on the one road with only two exits. That's not especially clever."},{"who":"BANDIT","mood":"normal","text":"You're brave for a girl with a crossbow on her back."},{"who":"REI","mood":"neutral","text":"And you're talking while both exits remain in reach of a spellcaster."}],"flags":{},"to":"D07"},"A11":{"id":"A11","title":"The long road","bg":"ROAD","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"With reliable directions, the party reached the northern gate safely. Isa slowed and looked toward the town. No proof of the merchant's scheme existed in their hands, and the larger crimes remained unsolved."},{"who":"ISA","mood":"sad","text":"I wonder how many people are still in trouble there."},{"who":"REI","mood":"neutral","text":"More than we can help in a single afternoon. We have a greater obligation ahead."},{"who":"ISA","mood":"neutral","text":"I know. I hate knowing."},{"who":"REI","mood":"happy","text":"For what it's worth, you helped someone today."},{"who":"ISA","mood":"smug","text":"And you laughed at me for crying about a dog."},{"who":"REI","mood":"laugh","text":"An extraordinary dog."}],"flags":{},"to":"E3"},"A12":{"id":"A12","title":"Following the messenger","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The messenger threaded through the narrow market lanes, passing a cobbler's stall and the west stable doors. At the alley's end, Isa and Rei saw him exchange a slip with one of three armed men."},{"who":"ISA","mood":"neutral","text":"That isn't an innocent shipping clerk."},{"who":"REI","mood":"neutral","text":"No. But we still don't know what's in the paper or the crates."}],"flags":{},"to":"A14"},"A13":{"id":"A13","title":"False seal on a crate","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"A merchant’s loading manifest led them behind the western stables. Through a gap in the old warehouse shutters, Rei spotted a crate bearing the same defunct cartographer’s seal. The doors were guarded, and the account books were still somewhere inside."},{"who":"REI","mood":"neutral","text":"The symbol connects the stall to these goods. Now we need lawful evidence of what they’re doing."},{"who":"ISA","mood":"neutral","text":"Then we find a way into the warehouse."}],"flags":{"warehouse_lead":true},"to":"A14"},"A14":{"id":"A14","title":"Outside the warehouse","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The messenger entered a storage building beside the stables. A watchman with a crooked dagger stood by the doors. A second guard watched the high window. Athena sniffed the narrow ventilation gap and growled."},{"who":"REI","mood":"neutral","text":"We can observe, enter quietly, or bring the captain. Each choice has a cost."},{"who":"ISA","mood":"smug","text":"I'm voting for whichever one ends with these men in a cell."}],"flags":{},"to":"A18"},"A15":{"id":"A15","title":"The account book","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"With the guards distracted and the upper entry secured, Isa and Rei entered the warehouse. Inside a desk drawer, beneath shipping manifests, Rei found an account book. They copied the entries, secured the original ledger, and slipped back out without alerting the watchmen."},{"who":"REI","mood":"neutral","text":"Dates, travelers’ descriptions, counterfeit routes, and payments. This is the record we needed."},{"who":"ISA","mood":"angry","text":"They treated people like shipments. We’re taking this to the captain."}],"flags":{"evidence":true,"crime_proven":true},"to":"A19"},"A16":{"id":"A16","title":"The captain's attention","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The Bellhaven guard captain listened to the account without interrupting. His scarred blind eye reflected the pale light; the other, green and sharp, studied Rei's journal."},{"who":"CAPTAIN","mood":"neutral","text":"A nervous merchant isn't a conviction. Show me a delivery note, a ledger, or a witness who saw goods stolen."},{"who":"ISA","mood":"annoyed","text":"So we're supposed to do your job for you?"},{"who":"CAPTAIN","mood":"stern","text":"You're asking me to imprison a citizen. I'm asking you for evidence."},{"who":"REI","mood":"neutral","text":"A reasonable standard. We may have a courier to follow."},{"who":"ISA","mood":"neutral","text":"Fine. Then we'll bring you something better than suspicion."}],"flags":{"guard_contacted":true},"to":"A14"},"D06":{"id":"D06","title":"Warehouse approach (A14)","bg":"VILLAGE","kind":"choice","options":[{"label":"Slip in through the high window","lines":[{"who":"REI","mood":"neutral","text":"I can quiet the hinge. Isa, you watch the street."},{"who":"ISA","mood":"smug","text":"And if someone arrives?"},{"who":"REI","mood":"laugh","text":"Try not to announce our names."},{"who":"NARRATION","mood":"neutral","text":"They reach the ledger without setting off the guard."}],"flags":{"stealth_success":true},"to":"A15","requires":[]},{"label":"Bring the captain with the messenger evidence","lines":[{"who":"CAPTAIN","mood":"stern","text":"I'll secure the building. You stay clear of the weapons."},{"who":"ISA","mood":"annoyed","text":"I'm a healer, not a porcelain doll."},{"who":"REI","mood":"happy","text":"She is surprisingly hard to break."},{"who":"NARRATION","mood":"neutral","text":"The guards force entry and secure the records."}],"flags":{"guard_contacted":true,"guard_support":true},"to":"A15","requires":[]},{"label":"Call out the bandits at the door","lines":[{"who":"ISA","mood":"mad","text":"COME OUT AND ANSWER FOR WHAT YOU'VE DONE!"},{"who":"REI","mood":"annoyed","text":"We could have knocked."},{"who":"NARRATION","mood":"neutral","text":"The red-scarfed leader appears with guards at his back."}],"flags":{},"to":"A20","requires":[]}],"lines":[]},"D07":{"id":"D07","title":"Escape or surrender","bg":"VILLAGE","kind":"choice","options":[{"label":"Surrender the bags","lines":[{"who":"ISA","mood":"sad","text":"Take them. Just let Athena pass."},{"who":"BANDIT","mood":"normal","text":"Wise choice."},{"who":"NARRATION","mood":"neutral","text":"They survive but lose nearly all portable supplies and coin."},{"who":"REI","mood":"neutral","text":"We can replace things. Not lives."}],"flags":{"resources_lost":true,"coins_delta":-18,"supplies_delta":-2},"to":"E4","requires":[]},{"label":"Counter the ambush with terrain and magic","lines":[{"who":"REI","mood":"neutral","text":"On my signal, cover the crossbowman."},{"who":"ISA","mood":"angry","text":"Gladly."},{"who":"NARRATION","mood":"neutral","text":"Isa's silver ward catches the bolt; Rei binds the narrow ledge. The bandits retreat, leaving their captain's route note."}],"flags":{"escaped_trap":true,"evidence":true},"to":"A21","requires":[]},{"label":"Try to flee across the tripwire","lines":[{"who":"ISA","mood":"scared","text":"Athena, this way!"},{"who":"REI","mood":"neutral","text":"Wait—the wire!"},{"who":"NARRATION","mood":"neutral","text":"Rei catches Isa by her cloak and hauls her clear, but the bandits seize their unattended packs."}],"flags":{"resources_lost":true,"coins_delta":-18,"supplies_delta":-2},"to":"E4","requires":[]}],"lines":[]},"A18":{"id":"A18","title":"Reconnaissance","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"From the shadow of the stable wall, they watched the guards change shifts. One checked the high window while another passed a ring of keys to the watchman at the door."},{"who":"REI","mood":"neutral","text":"That window has a simple alarm mark. We can disable it, ask the captain to enter with us, or draw them outside."},{"who":"ISA","mood":"neutral","text":"Good. Let’s choose a plan that keeps the ledger intact."}],"flags":{},"to":"D06"},"A19":{"id":"A19","title":"A captain with a ledger","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The captain laid the account book on his desk, pages spread beneath a weighted lantern. His expression hardened at the list of missing travelers."},{"who":"CAPTAIN","mood":"stern","text":"Dates. Descriptions. Payment records. This is what I needed."},{"who":"ISA","mood":"angry","text":"Then arrest the man with the feathered hat. And his friends."},{"who":"CAPTAIN","mood":"neutral","text":"I can move on the warehouse and the stall. The leader may still try to run."},{"who":"REI","mood":"neutral","text":"We should decide whether to secure the evidence, pursue the leader, or leave the operation to the guard."}],"flags":{},"to":"A22"},"A20":{"id":"A20","title":"The leader at the doors","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"BANDIT","mood":"normal","text":"Fancy robes and pretty jewelry. You two lost?"},{"who":"ISA","mood":"mad","text":"No. But your criminal operation is about to be."},{"who":"BANDIT","mood":"normal","text":"Don't want your life story. Want your purse."},{"who":"REI","mood":"smug","text":"You ask for gold and then insult the people holding it? Your technique needs work."},{"who":"BANDIT","mood":"normal","text":"I can fix that with a knife."},{"who":"NARRATION","mood":"neutral","text":"The guards shifted forward. Rei's spell was ready, but an uncontrolled fight could destroy the only records of the crimes."}],"flags":{},"to":"A23"},"A21":{"id":"A21","title":"Proof from the trap","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Back in Bellhaven, the captain inspected the route note taken from the attackers. The description matched the cartographer's forged map."},{"who":"CAPTAIN","mood":"stern","text":"This establishes a coordinated ambush. My guards will search the stall tonight."},{"who":"ISA","mood":"neutral","text":"And the missing people?"},{"who":"CAPTAIN","mood":"neutral","text":"We'll follow the trail. You have done more than most travelers would."},{"who":"REI","mood":"neutral","text":"We can remain and assist or continue our journey."}],"flags":{"evidence":true,"crime_proven":true},"to":"A22"},"D08":{"id":"D08","title":"Finish the map investigation (A19/A21)","bg":"VILLAGE","kind":"choice","options":[{"label":"Help secure the warehouse and merchant","lines":[{"who":"ISA","mood":"angry","text":"They've had their way long enough."},{"who":"REI","mood":"neutral","text":"Then we'll block the western road while the captain closes the doors."},{"who":"NARRATION","mood":"neutral","text":"The operation is dismantled and the stolen goods returned."}],"flags":{"operation_stopped":true},"to":"E1","requires":[]},{"label":"Pursue the leader yourself","lines":[{"who":"REI","mood":"neutral","text":"He knows the route out. We'll intercept him by the stables."},{"who":"ISA","mood":"smug","text":"I was hoping you'd say that."}],"flags":{},"to":"A23","requires":[]},{"label":"Leave the evidence with the captain and continue north","lines":[{"who":"ISA","mood":"sad","text":"I hate leaving before it's over."},{"who":"REI","mood":"neutral","text":"The guards have names, records, and authority now. Sarovar can't wait forever."}],"flags":{"investigation_handed_over":true},"to":"E3","requires":[]}],"lines":[]},"A22":{"id":"A22","title":"Decision handoff","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The captain's orders rang across the square as guards moved toward the west gate. Isa and Rei had to choose how much further they would intervene."}],"flags":{},"to":"D08"},"A23":{"id":"A23","title":"The final confrontation","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The bandit leader tried to escape down the stable passage. Rei raised a violet binding around the doorway. Isa stepped in front of him, furious but steady."},{"who":"BANDIT","mood":"normal","text":"You think a spell makes you better than me?"},{"who":"ISA","mood":"angry","text":"No. Not selling innocent people to thieves does."},{"who":"REI","mood":"neutral","text":"Put the knife down. We already have the ledger. You can surrender with all your remaining teeth."},{"who":"BANDIT","mood":"normal","text":"What teeth?"},{"who":"ISA","mood":"smug","text":"Exactly."},{"who":"NARRATION","mood":"neutral","text":"The guards arrived behind them. The leader dropped his blade. With the warehouse secured, the captain searched the accounting desk and discovered the ledger documenting the false routes, thefts, and payments. The arrests now rested on evidence, not merely on Isa and Rei's accusations.. # PASS TWO-B — MOPSY'S MAGNIFICENT MISFORTUNE"}],"flags":{"operation_stopped":true,"evidence":true,"crime_proven":true},"to":"E1"},"B01":{"id":"B01","title":"Former idol, current fire hazard","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy Hamham's shop had a disco ball. It also had enough glowing bottles to fill a laboratory, a little performance stage, three shelves of idol figures, and a stack of signed concert posters bearing a blue-haired hamster idol's unmistakable face. A song played from a glittering gramophone while pink light bounced over potion jars, spellbooks, and a crate labeled *Do Not Shake*. The two businesses appeared to have been combined by someone who refused to accept that retiring from J-pop meant retiring from show business."},{"who":"NARRATION","mood":"neutral","text":"A glass vial shattered behind the counter. A small voice cried, \"Success!\" Then, after a distinct pause, \"...Mostly!\""},{"who":"ISA","mood":"excited","text":"REI. THIS IS THE GREATEST SHOP I HAVE EVER SEEN."},{"who":"REI","mood":"neutral","text":"It has a fire extinguisher next to the stage curtains. That concerns me."},{"who":"MOPSY","mood":"excited","text":"WELCOME, WELCOME, WELCOOOOME! I'M MOPSY HAMHAM, FORMER IDOL SUPREME, CURRENT ALCHEMY SENSATION!"},{"who":"NARRATION","mood":"neutral","text":"A tiny hamster woman in extravagant blue curls and oversized spectacles leaped onto a stool, microphone raised to the ceiling."},{"who":"ISA","mood":"excited","text":"YOU WERE AN IDOL?!"},{"who":"MOPSY","mood":"happy","text":"Retired from the industry! Not from GLORY!"},{"who":"REI","mood":"smug","text":"How dignified. Do you also sell healing potions?"},{"who":"MOPSY","mood":"annoyed","text":"Wow. No applause, no photo, straight to business. Does he always make introductions feel like a tax audit?"},{"who":"ISA","mood":"laugh","text":"Worse. He enjoys it."},{"who":"REI","mood":"laugh","text":"I have several excellent reviews."},{"who":"MOPSY","mood":"happy","text":"Then let me give you your first bad one!"}],"flags":{},"to":"B02"},"B02":{"id":"B02","title":"The cost of protection","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Isa wandered among dazzling bottled spells and collectible figurines until she noticed the broken rear lock, smashed shelving, and an empty velvet-lined box. Beside the wreckage, a glittering festival poster lay crumpled on the floor."},{"who":"ISA","mood":"neutral","text":"Mopsy, who broke your door?"},{"who":"MOPSY","mood":"sad","text":"The protection men. They said if I didn't pay, unfortunate things would happen. I paid twice. Then they came back anyway."},{"who":"ISA","mood":"mad","text":"THEY BROKE INTO YOUR SHOP?"},{"who":"REI","mood":"neutral","text":"What did they take?"},{"who":"MOPSY","mood":"neutral","text":"Healing tonics, moonmint, half my inventory of sparkly vials... and my only stabilizing crystal."},{"who":"ISA","mood":"sad","text":"Oh, honey."},{"who":"MOPSY","mood":"sad","text":"I was supposed to perform a reunion concert for the spring festival. Then they stole the fundraiser money. Nobody wanted a party while everyone was frightened."},{"who":"REI","mood":"neutral","text":"Do you know who they are?"},{"who":"MOPSY","mood":"neutral","text":"One ugly man with a red scarf and several missing teeth. He keeps coming back to remind me how small I am."},{"who":"ISA","mood":"angry","text":"Being small doesn't mean you deserve any of this."},{"who":"MOPSY","mood":"nervous","text":"No, but it does mean I can't reach the top shelf without a ladder."},{"who":"NARRATION","mood":"neutral","text":"Isa smiled despite herself. Rei studied the broken hinge; its splintered edge bore the same muddy boot print as the rear threshold."}],"flags":{},"to":"D09"},"D09":{"id":"D09","title":"What will you say to Mopsy?","bg":"SHOP","kind":"choice","options":[{"label":"Volunteer to recover her things","lines":[{"who":"ISA","mood":"neutral","text":"We'll help. Nobody gets to bully you out of your own shop."},{"who":"MOPSY","mood":"excited","text":"REALLY?! OH, MY STARS! I COULD KISS BOTH OF YOU!"},{"who":"REI","mood":"neutral","text":"Let's begin with information rather than physical affection."}],"flags":{"mopsy_helped":true,"mopsy_trust":2},"to":"B03","requires":[]},{"label":"Offer a fair trade for supplies","lines":[{"who":"REI","mood":"neutral","text":"We'll help retrieve your property. In return, we need medicine for the road. Only what you can spare."},{"who":"MOPSY","mood":"confused","text":"You'll help without demanding all my stock?"},{"who":"ISA","mood":"annoyed","text":"We're not the bandits."},{"who":"MOPSY","mood":"happy","text":"Then you may have two tonics and a signed portrait of the greatest retired idol alive!"}],"flags":{"mopsy_helped":true,"mopsy_trust":1,"tonic_reward":true},"to":"B03","requires":[]},{"label":"Ask questions but make no promise","lines":[{"who":"REI","mood":"neutral","text":"Tell us precisely what happened. We may be able to bring the guards evidence."},{"who":"MOPSY","mood":"neutral","text":"They came after sunset. One mentioned a warehouse beyond the stables."},{"who":"ISA","mood":"neutral","text":"That's something. We'll decide what we can do once we know more."}],"flags":{"mopsy_trust":0,"warehouse_hint":true},"to":"B04","requires":[]},{"label":"Decline because Sarovar is urgent","lines":[{"who":"ISA","mood":"sad","text":"I'm so sorry, Mopsy. Someone needs our help far to the north. We can't promise we'll return in time."},{"who":"MOPSY","mood":"sad","text":"Oh. Of course. Heroes have important schedules."},{"who":"REI","mood":"neutral","text":"We'll report what happened to the guards before we leave."},{"who":"MOPSY","mood":"happy","text":"Then my comeback concert will have to wait for another season!"}],"flags":{"mopsy_declined":true},"to":"B05","requires":[]}],"lines":[]},"B03":{"id":"B03","title":"An inventor worth listening to","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy led them behind the counter to a workbench covered with copper coils, paper calculations, and a bottle of gold liquid that ticked audibly when moved. Rei examined the construction before touching anything."},{"who":"REI","mood":"neutral","text":"You've designed a regulating lattice that uses the reaction's own energy to control its release. That's extremely clever."},{"who":"MOPSY","mood":"excited","text":"SOMEBODY UNDERSTANDS MY SCIENCE!"},{"who":"ISA","mood":"smug","text":"He is terribly clever. It's his worst quality."},{"who":"REI","mood":"happy","text":"You are my loudest supporter."},{"who":"ISA","mood":"annoyed","text":"I AM NOT—oh, forget it."},{"who":"MOPSY","mood":"happy","text":"The stolen crystal kept the bottle stable. Without it, the mixture might react before it's thrown. It did once blow a ceiling into a different room."},{"who":"REI","mood":"neutral","text":"Then we don't use it untested."},{"who":"ISA","mood":"confused","text":"How many ceilings have you owned?"},{"who":"MOPSY","mood":"smug","text":"Depends whether you're counting the landlord's."},{"who":"NARRATION","mood":"neutral","text":"Under the glitter and the theater lights, Mopsy knew precisely what she was doing. The real flaw was the missing ingredient."}],"flags":{},"to":"B06"},"B04":{"id":"B04","title":"Information first","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy unfolded a shopping list containing the stolen quantities and dates. Between the doodled stars were neat delivery stamps and receipts."},{"who":"REI","mood":"neutral","text":"These timestamps can corroborate a theft. Did anyone see the men carry the crates?"},{"who":"MOPSY","mood":"neutral","text":"The bakery apprentice. He dropped his tray when they threatened him."},{"who":"ISA","mood":"neutral","text":"Then perhaps the captain can help if we bring the receipts and a witness."},{"who":"MOPSY","mood":"sad","text":"He turned me away last time."},{"who":"ISA","mood":"angry","text":"Then this time we'll come with evidence."},{"who":"NARRATION","mood":"neutral","text":"Mopsy studied them for a moment and pushed the receipt book into Isa's hands."}],"flags":{"receipts":true,"warehouse_hint":true},"to":"B07"},"B05":{"id":"B05","title":"A promise not made","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Outside the shop, Mopsy waved from behind the window. The gramophone resumed its cheerful tune. Isa kept looking back."},{"who":"ISA","mood":"sad","text":"She was trying not to cry."},{"who":"REI","mood":"neutral","text":"Yes. She was."},{"who":"ISA","mood":"neutral","text":"You think we're doing the wrong thing?"},{"who":"REI","mood":"neutral","text":"I think there are more people in need than we can reach before the moon breaks. That doesn't make leaving pleasant."},{"who":"ISA","mood":"annoyed","text":"You could at least be worse at being right."},{"who":"REI","mood":"happy","text":"I have tried."}],"flags":{},"to":"E3"},"B06":{"id":"B06","title":"The extraordinary Hamham Special","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy lowered a velvet cushion bearing a sparkling golden bottle. The label read *HAMHAM SPECIAL, VERSION 19.4 — PLEASE STAND BACK*. A small lock secured the stopper."},{"who":"MOPSY","mood":"excited","text":"My SPECIAL explosive potion! Enemies hate it! Walls hate it! My landlord HATES it!"},{"who":"ISA","mood":"laugh","text":"Why does your landlord hate it?"},{"who":"MOPSY","mood":"happy","text":"BECAUSE SHE LACKS VISION!"},{"who":"REI","mood":"smug","text":"And presumably walls."},{"who":"MOPSY","mood":"laugh","text":"I LIKE HIM!"},{"who":"ISA","mood":"laugh","text":"Don't encourage him."},{"who":"NARRATION","mood":"neutral","text":"Rei turned the bottle until the empty crystal socket caught the light."},{"who":"REI","mood":"neutral","text":"It won't be safe until we recover the crystal or build a replacement. That's not a guess. The pressure is already rising."},{"who":"MOPSY","mood":"nervous","text":"So... no shaking, no heat, no dropping, and absolutely no unscrewing the stopper indoors."},{"who":"ISA","mood":"neutral","text":"Understood."}],"flags":{"unstable_formula_known":true},"to":"B08"},"D10":{"id":"D10","title":"How should we handle Mopsy’s potion?","bg":"SHOP","kind":"choice","options":[{"label":"Recover Mopsy's original stabilizing crystal","lines":[{"who":"ISA","mood":"neutral","text":"We'll retrieve the original. No reason to experiment with a bomb before we need one."},{"who":"MOPSY","mood":"happy","text":"Safety FIRST! Fame SECOND!"},{"who":"REI","mood":"smug","text":"I suspect fame usually comes first."}],"flags":{"seek_original_crystal":true,"mopsy_accompanies":true},"to":"B09","requires":[]},{"label":"Help Rei construct a replacement and test it properly","lines":[{"who":"REI","mood":"neutral","text":"Her design is sound. I can reproduce the stabilizer with a prepared arcane lattice, but it needs a controlled trial."},{"who":"MOPSY","mood":"excited","text":"A COLLABORATION SPECIAL!"},{"who":"ISA","mood":"annoyed","text":"NO EXPLOSIONS IN THE STORE."}],"flags":{"seek_replacement":true,"mopsy_accompanies":true},"to":"B10","requires":[]},{"label":"Take an unfinished bottle without testing","lines":[{"who":"MOPSY","mood":"scared","text":"No! That is NOT stable. Do not use it until the crystal is installed!"},{"who":"REI","mood":"neutral","text":"I won't pretend this is safe. If you insist on carrying it, keep the seal intact."},{"who":"ISA","mood":"neutral","text":"We'll label it and keep it away from Athena."}],"flags":{"unstable_potion":true,"stable_potion":false,"warning_acknowledged":true,"mopsy_accompanies":true},"to":"B09","requires":[]}],"lines":[]},"B07":{"id":"B07","title":"Proof for the captain","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The baker's apprentice confirmed that men in red scarves had carried Mopsy's blue crate toward the old stables. He had been frightened into silence by a threat against his family. Rei wrote down his account without pressing for details the boy couldn't know."},{"who":"ISA","mood":"neutral","text":"Thank you. You did something brave."},{"who":"REI","mood":"neutral","text":"The receipts and witness connect the stolen goods to the warehouse. We can seek official help now."},{"who":"NARRATION","mood":"neutral","text":"With no promise of further aid to Mopsy, they could hand the evidence to the captain or investigate themselves."}],"flags":{},"to":"B11"},"B08":{"id":"B08","title":"A lesson in stagecraft","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"On the wall beside the workbench hung a concert poster of a younger Mopsy under a shower of confetti, surrounded by cheering fans. The poster's corners were curled from years of careful unfolding."},{"who":"ISA","mood":"happy","text":"You really performed in concert halls?"},{"who":"MOPSY","mood":"happy","text":"Everywhere! The Hamham World Tour! Five cities! Four sold-out shows! One wardrobe malfunction I refuse to discuss!"},{"who":"REI","mood":"smug","text":"A distinguished career. Why retire?"},{"who":"MOPSY","mood":"sad","text":"The touring got lonely. Everyone loved the costumes. Not many wanted to know what was underneath them. And I wanted to make things. Real things. Things people could carry home."},{"who":"ISA","mood":"sad","text":"Your shop matters to you."},{"who":"MOPSY","mood":"neutral","text":"It's mine. I made it with my own paws. Even the landlord's threats can't take that from me."},{"who":"REI","mood":"neutral","text":"Your calculations are excellent. I mean that."},{"who":"MOPSY","mood":"excited","text":"AN INTELLECTUAL FAN! I SHALL PUT YOUR NAME ON THE VIP LIST!"},{"who":"ISA","mood":"smug","text":"His ego barely fits through doors already."},{"who":"REI","mood":"laugh","text":"Then please ensure the doors are wide."}],"flags":{},"to":"D10"},"B09":{"id":"B09","title":"The stolen-goods warehouse","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy agreed to accompany them, promising to keep her voice down as they reached the warehouse beside the western stables. Through the shutters she spotted her blue crate, decorated with gold stars. Two guards stood outside; a third patrolled the loft."},{"who":"MOPSY","mood":"excited","text":"MY THINGS!"},{"who":"REI","mood":"annoyed","text":"That was your quiet voice?"},{"who":"MOPSY","mood":"neutral","text":"My stage whisper."},{"who":"ISA","mood":"neutral","text":"We need the crystal intact. Let’s not rush in and destroy the evidence."}],"flags":{},"to":"B12"},"B10":{"id":"B10","title":"Rei’s first attempt fails","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei suspended an arcane lattice over Mopsy’s workbench. The temporary crystal looked convincing until the first thread of violet current passed through it."},{"who":"REI","mood":"neutral","text":"The pattern is holding. Now—very little pressure."},{"who":"NARRATION","mood":"neutral","text":"A hairline crack spread through the lattice. Isa raised a shield just as the test vial burst against its inner surface. Glitter rained harmlessly across the shop, but the imitation crystal shattered."},{"who":"ISA","mood":"scared","text":"That was the safe test?"},{"who":"REI","mood":"annoyed","text":"Yes. That is why we tested a sample rather than the bottle. The crystal can contain energy, but it cannot bleed it off."},{"who":"MOPSY","mood":"nervous","text":"My original stabilizer drinks the extra magic! Like a very thirsty microphone!"},{"who":"ISA","mood":"neutral","text":"We need a way to release the pressure slowly. What do we try next?"}],"flags":{"stable_potion":true,"unstable_potion":false,"mopsy_trust":2},"to":"D22"},"D11":{"id":"D11","title":"How should we approach the warehouse?","bg":"WAREHOUSE","kind":"choice","options":[{"label":"Slip through an upper window after inspecting its ward","lines":[{"who":"REI","mood":"neutral","text":"The window's alarm is only a single rune. I'll silence it."},{"who":"ISA","mood":"smug","text":"You do love a puzzle."},{"who":"REI","mood":"happy","text":"Especially one that doesn't argue with me."},{"who":"ISA","mood":"annoyed","text":"I HEARD THAT."}],"flags":{"stealth_success":true},"to":"B13","requires":[]},{"label":"Distract the guards while Rei enters","lines":[{"who":"ISA","mood":"excited","text":"GENTLEMEN! ARE YOU HIRING?"},{"who":"GUARD","mood":"neutral","text":"What?"},{"who":"ISA","mood":"smug","text":"I have exceptional skills in yelling at idiots."},{"who":"NARRATION","mood":"neutral","text":"Rei slips past as she launches into an absurd employment interview."}],"flags":{"diversion_success":true},"to":"B13","requires":[]},{"label":"Demand the stolen crate at the door","lines":[{"who":"ISA","mood":"angry","text":"OPEN THIS DOOR! THAT CRATE BELONGS TO MOPSY!"},{"who":"MOPSY","mood":"excited","text":"AND I WANT MY RECEIPT!"},{"who":"REI","mood":"annoyed","text":"Our element of surprise has left the premises."}],"flags":{},"to":"B14","requires":[]},{"label":"Ask the town guards for assistance","lines":[{"who":"ISA","mood":"neutral","text":"We have a shipping note and a stolen crate to report. Let’s get help from the guards before going inside."},{"who":"REI","mood":"neutral","text":"Agreed. We should show them what we actually found, not claim we have evidence we haven’t seen."}],"flags":{"guard_contacted":true},"to":"B_GUARD_INTRO","requires":[]}],"lines":[]},"B11":{"id":"B11","title":"A lawful route","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The captain took the bakery apprentice's statement and matched the receipts to the reported theft. He agreed to investigate the warehouse, but warned that witnesses alone might not link the larger operation to every missing shipment."},{"who":"CAPTAIN","mood":"neutral","text":"I can open an inquiry. If you intend to follow the thieves, do not endanger the apprentice."},{"who":"ISA","mood":"neutral","text":"We won't."},{"who":"REI","mood":"neutral","text":"We can proceed to the warehouse with caution or leave the inquiry in your hands."}],"flags":{"guard_contacted":true},"to":"B16"},"B12":{"id":"B12","title":"The warehouse approach","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei counted the guards' rotations while Mopsy hummed the chorus of a song under her breath. A small window on the north wall stood open a finger's width."}],"flags":{},"to":"D11"},"B13":{"id":"B13","title":"What they actually stole","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Inside, Mopsy's blue crate lay open. The healing potions and glitter were scattered in careless piles, but the small velvet compartment where the stabilizing crystal belonged was empty."},{"who":"MOPSY","mood":"scared","text":"Where is it?"},{"who":"REI","mood":"neutral","text":"Taken out deliberately."},{"who":"ISA","mood":"neutral","text":"Why steal one crystal and leave everything else?"},{"who":"NARRATION","mood":"neutral","text":"On a desk nearby, Rei found a shipping order for enchanted stones, delivered to a buyer whose name had been scratched out. The bandits were not merely stealing goods to sell in town; someone was paying them to locate specific magical materials."},{"who":"REI","mood":"neutral","text":"This could be part of a larger trade. We don't know the buyer's motive yet."},{"who":"ISA","mood":"angry","text":"But we know who's been taking the goods."},{"who":"MOPSY","mood":"sad","text":"I just want my shop back."}],"flags":{"magical_buyer_hint":true,"warehouse_evidence":true},"to":"B17"},"B14":{"id":"B14","title":"The bandit leader arrives","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The guard doors opened. The red-scarfed leader strode inside, followed by men with knives at their belts. He grinned through the gaps in his teeth."},{"who":"BANDIT","mood":"normal","text":"Well, well. An idol hamster and two rich travelers. What a strange little audience."},{"who":"MOPSY","mood":"angry","text":"I AM AN ALCHEMIST WITH A REPUTABLE FORMER CAREER!"},{"who":"BANDIT","mood":"normal","text":"You can perform after you pay your protection fee."},{"who":"ISA","mood":"angry","text":"You don't get to charge people for the privilege of living without your threats."},{"who":"REI","mood":"neutral","text":"Put down the weapons. There are three of you and two of us, but those aren't the odds that matter."},{"who":"BANDIT","mood":"normal","text":"You always talk this much?"},{"who":"REI","mood":"smug","text":"Usually less. You're inspiring."}],"flags":{},"to":"B18"},"B15":{"id":"B15","title":"The guards take the case","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Isa and Rei withdrew to the town guard post before entering the warehouse. A guard listened to their account, then introduced them to the Bellhaven Guard Captain."},{"who":"CAPTAIN","mood":"stern","text":"I can investigate a report of stolen goods. But I need witnesses or records before I can make arrests."},{"who":"ISA","mood":"neutral","text":"We can tell you where Mopsy’s supplies were taken. We haven’t seen what is inside."},{"who":"REI","mood":"neutral","text":"The warehouse remains a lead, not proof."},{"who":"CAPTAIN","mood":"neutral","text":"Then I’ll assign a patrol. It may take time."},{"who":"MOPSY","mood":"nervous","text":"Please tell them the missing stabilizer makes my shop dangerous. And my landlord very loud!"}],"flags":{},"to":"E3"},"B16":{"id":"B16","title":"Help or depart","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The archive of receipts was now in the captain's hands. With no personal promise to Mopsy and the moon still broken, the party could choose to continue investigating or go north."}],"flags":{},"to":"B19"},"D12":{"id":"D12","title":"How far to follow Mopsy's case","bg":"VILLAGE","kind":"choice","options":[{"label":"Investigate the warehouse personally","lines":[{"who":"ISA","mood":"neutral","text":"The apprentice risked speaking. We should at least see what the thieves are hiding."},{"who":"REI","mood":"neutral","text":"Then we proceed carefully."}],"flags":{"warehouse_lead":true},"to":"B25","requires":[]},{"label":"Let the guards take over","lines":[{"who":"ISA","mood":"sad","text":"I wish we could stay. The Goddess is waiting."},{"who":"REI","mood":"neutral","text":"We've given the captain something actionable."}],"flags":{},"to":"E3","requires":[]}],"lines":[]},"B17":{"id":"B17","title":"The empty velvet compartment","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy’s blue crate was open, but the velvet compartment for her stabilizer had been cut out. Someone had removed the one piece that made the Hamham Special safe."},{"who":"MOPSY","mood":"scared","text":"They took the most important part. The actual shiny part!"},{"who":"REI","mood":"neutral","text":"The packing list records the missing stabilizer separately. There is a second shipment ledger here, but some pages have been torn out."},{"who":"ISA","mood":"neutral","text":"And there are fresh marks on the floor leading toward the upstairs storeroom. We have a choice: records, locks, or witnesses."}],"flags":{"original_crystal_recovered":true,"evidence":true},"to":"D24"},"B18":{"id":"B18","title":"A choice before violence","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei placed his hand near the binding glyph concealed beneath his sleeve. Isa kept herself between the bandits and Mopsy. The leader examined their purses and smiled."},{"who":"BANDIT","mood":"normal","text":"You want your trinkets? Fine. Pay the toll and we'll call it even."},{"who":"ISA","mood":"angry","text":"They were hers to begin with!"},{"who":"REI","mood":"neutral","text":"We can stall him, restrain him, pay and leave, or use a potion—*if* we have a safe one."}],"flags":{},"to":"B21"},"B19":{"id":"B19","title":"Decision handoff","bg":"VILLAGE","kind":"scene","lines":[],"flags":{},"to":"D12"},"B20":{"id":"B20","title":"The safer formula","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei examined the recovered crystal in a shielded recess. It showed no fractures, but he refused to assume that meant it was safe."},{"who":"REI","mood":"neutral","text":"I’ll set the crystal and test a small sample first. If it spikes, we stop."},{"who":"MOPSY","mood":"nervous","text":"I trust you. I’m only shaking because I am FULL OF ARTISTIC ENERGY."},{"who":"NARRATION","mood":"neutral","text":"The first test steadied. A second, higher-pressure test produced a controlled flash inside the ward. Nothing escaped the vessel."},{"who":"ISA","mood":"neutral","text":"Now I believe you when you say it’s stable."},{"who":"REI","mood":"neutral","text":"That is what testing is for."}],"flags":{"stable_potion":true},"to":"B14"},"D13":{"id":"D13","title":"Face the bandit (B18)","bg":"VILLAGE","kind":"choice","options":[{"label":"Use the *tested stable* Hamham Special","lines":[{"who":"ISA","mood":"neutral","text":"Mopsy, is the seal secure?"},{"who":"MOPSY","mood":"excited","text":"ONE HUNDRED PERCENT!"},{"who":"REI","mood":"neutral","text":"Away from the support beams. On the leader's feet."},{"who":"NARRATION","mood":"neutral","text":"Mopsy hurls the potion. It detonates in a dazzling, nonlethal burst at the leader's boots. His face is coated in soot, his scarf smokes, and an already loose tooth falls from his mouth."},{"who":"BANDIT","mood":"bombed","text":"Was that one of mine?"},{"who":"ISA","mood":"laugh","text":"I don't think it was attached before."}],"flags":{"bandit_bombed":true,"operation_stopped":true},"to":"B22","requires":["stable_potion=true"]},{"label":"Bind the men with Rei's spell","lines":[{"who":"REI","mood":"neutral","text":"Weapons on the ground. Now."},{"who":"NARRATION","mood":"neutral","text":"Violet threads lock around the weapons and the exit. Isa drags Mopsy clear as the bandits stumble into their own rope."},{"who":"ISA","mood":"smug","text":"That was extremely satisfying."},{"who":"REI","mood":"laugh","text":"I aim to please."}],"flags":{"bandits_bound":true,"operation_stopped":true,"evidence":true},"to":"B23","requires":[]},{"label":"Pay and retreat","lines":[{"who":"ISA","mood":"sad","text":"Take the coin. Leave her alone."},{"who":"BANDIT","mood":"normal","text":"That's more like it."},{"who":"REI","mood":"neutral","text":"We can replace the coin; we can't replace one another."},{"who":"NARRATION","mood":"neutral","text":"The thieves take supplies and let the party go, with Mopsy still in danger."}],"flags":{"resources_lost":true,"coins_delta":-18,"supplies_delta":-2},"to":"E4B","requires":[]},{"label":"*Ignore warnings* and unseal the unstable bottle in the enclosed room","lines":[{"who":"WARNING","mood":"neutral","text":"Mopsy and Rei warned this bottle may detonate in your hands. This is a potentially fatal choice."},{"who":"MOPSY","mood":"scared","text":"DON'T OPEN THAT! IT HAS NO STABILIZER!"},{"who":"REI","mood":"scared","text":"ISA, PUT IT DOWN."},{"who":"NARRATION","mood":"neutral","text":"The seal clicks free. A white flash fills the warehouse before either spellcaster can contain the reaction."}],"flags":{"fatal_misuse":true},"to":"E6","requires":["unstable_potion=true"]},{"label":"Run with recovered goods","lines":[{"who":"REI","mood":"neutral","text":"Back door, now!"},{"who":"ISA","mood":"neutral","text":"Mopsy, keep moving!"},{"who":"NARRATION","mood":"neutral","text":"The party escapes with what it can carry. The bandits remain active."}],"flags":{},"to":"E3","requires":[]}],"lines":[]},"B21":{"id":"B21","title":"Decision handoff","bg":"WAREHOUSE","kind":"scene","lines":[],"flags":{},"to":"D13"},"B22":{"id":"B22","title":"The landlord arrives","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The tested Hamham Special erupted in a controlled spray of brilliant light. When the glitter cleared, the bandit leader was standing in harmless soot, too stunned to speak."},{"who":"MOPSY","mood":"excited","text":"MOPSY HAMHAM! ONE! BANDITS! ZERO!"},{"who":"ISA","mood":"neutral","text":"We should secure these men and recover the stolen supplies."},{"who":"REI","mood":"neutral","text":"We can call the guards with the evidence and meet them at the loading gate."},{"who":"NARRATION","mood":"neutral","text":"With the guards overseeing the seized cargo, the party returned to Mopsy’s shop. Her celebration had barely begun."}],"flags":{},"to":"E2"},"B23":{"id":"B23","title":"The consequences of restraint","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The captain arrived to find the bandits wrapped in a lattice of violet magic and their stolen goods stacked for inspection. The ledger recovered from the warehouse connected their operation to raids across the district."},{"who":"CAPTAIN","mood":"stern","text":"I'll take the prisoners from here."},{"who":"MOPSY","mood":"happy","text":"And my shop survives!"},{"who":"ISA","mood":"neutral","text":"We can ask the captain to pursue the wider operation before we leave."}],"flags":{"evidence":true,"crime_proven":true},"to":"B24"},"D14":{"id":"D14","title":"Finish Mopsy's route","bg":"VILLAGE","kind":"choice","options":[{"label":"Stay until the operation is dismantled","lines":[{"who":"ISA","mood":"neutral","text":"We can't leave the other merchants at their mercy."},{"who":"REI","mood":"neutral","text":"Then we'll help close the roads and secure the books."},{"who":"NARRATION","mood":"neutral","text":"A coordinated search arrests the remaining accomplices and returns the stolen crates."}],"flags":{"operation_stopped":true},"to":"E1B","requires":[]},{"label":"Leave with Mopsy safe but other crimes unresolved","lines":[{"who":"MOPSY","mood":"happy","text":"You got my things back! That's more than I dared hope."},{"who":"ISA","mood":"sad","text":"I wish we could fix everything."},{"who":"REI","mood":"neutral","text":"Today we fixed something real."}],"flags":{"mopsy_helped":true},"to":"E3","requires":[]}],"lines":[]},"B24":{"id":"B24","title":"Decision handoff","bg":"VILLAGE","kind":"scene","lines":[],"flags":{},"to":"D14"},"C01":{"id":"C01","title":"Athena refuses to move","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Later that day, Athena stopped abruptly near the bakery. She pricked her ears toward a narrow alley, where someone was crying behind stacked barrels."},{"who":"ISA","mood":"neutral","text":"Athena, what is it?"},{"who":"REI","mood":"neutral","text":"Not a snack this time. Look at her ears."},{"who":"ISA","mood":"smug","text":"You’ve started speaking fluent dog?"},{"who":"REI","mood":"smug","text":"I live with two very expressive creatures."},{"who":"ISA","mood":"annoyed","text":"REI."},{"who":"NARRATION","mood":"neutral","text":"A small figure emerged from behind the barrels, wearing a familiar patched cap. His green scarf was muddy now, and his hands shook. Isa recognized him immediately."},{"who":"ISA","mood":"scared","text":"Tobin? What happened?"},{"who":"TOBIN","mood":"scared","text":"Isa! Rei! I didn’t know who else to ask."},{"who":"REI","mood":"neutral","text":"Where’s Biscuit? Is he all right?"},{"who":"TOBIN","mood":"neutral","text":"He’s safe at home with Mother. He was resting when I left to help Father with a delivery."},{"who":"ISA","mood":"neutral","text":"Good. You’re safe with us too. Tell us what happened."},{"who":"TOBIN","mood":"scared","text":"Three men stole Father’s delivery wagon near the western stables. They said they’d hurt our family if I told anyone."},{"who":"ISA","mood":"angry","text":"They threatened you?"},{"who":"REI","mood":"neutral","text":"How many? Did you recognize any of them?"},{"who":"TOBIN","mood":"scared","text":"Three. One wore a red scarf. He asked for a silver box, but I didn’t know which one he meant. They took the whole wagon."},{"who":"NARRATION","mood":"neutral","text":"Athena moved between Tobin and the alley entrance. Isa crouched beside him, while Rei studied the wheel marks that led toward the stables."}],"flags":{},"to":"D15"},"D15":{"id":"D15","title":"How will Isa and Rei keep Tobin safe?","bg":"VILLAGE","kind":"choice","options":[{"label":"Escort Tobin home","lines":[{"who":"ISA","mood":"neutral","text":"We’ll bring you home to your father first. You shouldn’t have to face this alone."},{"who":"TOBIN","mood":"worried","text":"He’ll be worried. Mother told me to be careful when I went back out."},{"who":"REI","mood":"neutral","text":"And your father can tell us what was inside the wagon."}],"flags":{"tobin_safe":true,"family_trust":true},"to":"C02","requires":[]},{"label":"Follow the cart tracks after finding him shelter","lines":[{"who":"ISA","mood":"neutral","text":"Does the baker know your family?"},{"who":"TOBIN","mood":"neutral","text":"Yes. Mrs. Elwin is Mother’s friend. She lets me help in the shop sometimes."},{"who":"NARRATION","mood":"neutral","text":"Mrs. Elwin recognized Tobin, ushered him inside, and promised to send a runner to his parents immediately. She would keep him in the locked back room until his family came for him."},{"who":"REI","mood":"neutral","text":"Good. We can follow the fresh tracks without putting Tobin in danger."},{"who":"TOBIN","mood":"scared","text":"Please find Father’s wagon. And be careful."}],"flags":{"tobin_safe":true,"tracks_found":true},"to":"C03","requires":[]},{"label":"Bring Tobin to the captain","lines":[{"who":"REI","mood":"neutral","text":"The captain should record the threat while it’s fresh. We’ll go with you."},{"who":"ISA","mood":"neutral","text":"I won’t leave you with strangers."},{"who":"TOBIN","mood":"happy","text":"Okay. Thank you for helping Biscuit, too."}],"flags":{"tobin_safe":true,"guard_contacted":true},"to":"C04","requires":[]}],"lines":[]},"C02":{"id":"C02","title":"A father's relief","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Isa, Rei, and Tobin reached his family’s modest home near the western gate. His father opened the door, grey-haired and tired, his clothes carefully patched. He nearly dropped the laundry in his hands when he saw his son."},{"who":"FATHER","mood":"worried","text":"Tobin! I’ve been looking everywhere."},{"who":"TOBIN","mood":"happy","text":"I’m all right, Father. These are Isa and Rei—the travelers who saved Biscuit this morning."},{"who":"FATHER","mood":"relieved","text":"Your mother told me about them. First you helped our dog, and now you’ve brought my boy home. Thank you."},{"who":"ISA","mood":"angry","text":"He was very brave. But the men who stole your delivery wagon threatened him."},{"who":"FATHER","mood":"worried","text":"They threatened my son?"},{"who":"REI","mood":"neutral","text":"He’s safe now. The thieves wanted a silver box. Can you tell us about the shipment?"},{"who":"FATHER","mood":"neutral","text":"An iron chest with silver fittings. A cloaked stranger paid me to carry it north. The rest was ordinary stock: medicine, cloth, and grain."},{"who":"ISA","mood":"neutral","text":"Where was it meant to go?"},{"who":"FATHER","mood":"worried","text":"An old lunar shrine beyond the northern fields. I accepted the delivery because we needed the money."},{"who":"NARRATION","mood":"neutral","text":"He produced the original order slip. Its seal showed three hooked lines around a ring."},{"who":"REI","mood":"neutral","text":"That resembles a lunar containment mark. It doesn’t tell us what’s inside, though."},{"who":"ISA","mood":"neutral","text":"Then we find the chest before the thieves deliver it."}],"flags":{"cargo_description":true,"shrine_destination_known":true},"to":"C05"},"C03":{"id":"C03","title":"Fresh tracks","bg":"ROAD","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Fresh wagon ruts turned toward the western stables, then vanished beneath the dry wooden floor of a loading shed. The thieves had taken the cart directly to the warehouse rather than the northern road."},{"who":"ISA","mood":"neutral","text":"At least they didn't get far."},{"who":"REI","mood":"neutral","text":"It may be a temporary holding place. We don't know what they were after."},{"who":"ATHENA","mood":"angry","text":"Grrr."},{"who":"NARRATION","mood":"neutral","text":"Athena sniffed a torn piece of canvas caught beneath a wheel. It was stained with an unfamiliar violet dust."},{"who":"ISA","mood":"confused","text":"That's not grain."},{"who":"REI","mood":"neutral","text":"No. A residue from something enchanted. We should be careful with the cargo."}],"flags":{"warehouse_lead":true,"residue_found":true},"to":"C06"},"C04":{"id":"C04","title":"Testimony before pursuit","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The captain listened while Tobin described the men who stole his father’s delivery wagon and threatened his family. He knelt to speak at the boy’s eye level."},{"who":"CAPTAIN","mood":"stern","text":"You did the right thing by asking for help. I’ll send a patrol to the stables and have the thieves’ description circulated."},{"who":"TOBIN","mood":"scared","text":"Will they come after us?"},{"who":"CAPTAIN","mood":"neutral","text":"Not if we can prevent it. Your family will be notified and watched over."},{"who":"ISA","mood":"neutral","text":"I’m taking him home. His mother and Biscuit will be worried sick."},{"who":"REI","mood":"neutral","text":"And we need to speak with his father about the cargo."},{"who":"NARRATION","mood":"neutral","text":"The captain arranged a guard escort. Tobin went with Isa and Rei to his family home, while the patrol set off toward the western stables."}],"flags":{"guard_contacted":true},"to":"C02"},"C05":{"id":"C05","title":"The scratched order","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Tobin's father held the order in the window light. Its ink was fading, but the shrine destination was clear. He remembered a hooded courier paying in unusually old silver coins."},{"who":"FATHER","mood":"worried","text":"I never saw his face. He kept asking whether I'd opened the box."},{"who":"ISA","mood":"confused","text":"Did you?"},{"who":"FATHER","mood":"neutral","text":"No. It sounded as if something inside was tapping against the lid."},{"who":"REI","mood":"neutral","text":"There may be a binding or an unstable magical source inside. We should gather information before breaking its seal."},{"who":"ISA","mood":"neutral","text":"Warehouse, archive, or shrine. Which will tell us the most?"}],"flags":{"shrine_known":true},"to":"C07"},"D16":{"id":"D16","title":"Pursue the cargo lead","bg":"VILLAGE","kind":"choice","options":[{"label":"Go to the warehouse to recover the chest","lines":[{"who":"ISA","mood":"neutral","text":"If it's dangerous, leaving it with thieves is worse."},{"who":"REI","mood":"neutral","text":"Agreed. We'll retrieve it without opening it."}],"flags":{"warehouse_lead":true},"to":"C06","requires":[]},{"label":"Research the symbol in the archive","lines":[{"who":"REI","mood":"happy","text":"The town registry may have old temple records. Better to know the seal before testing it."},{"who":"ISA","mood":"smug","text":"You've found an excuse to visit a library."},{"who":"REI","mood":"laugh","text":"One must take joy where one can."}],"flags":{},"to":"C08","requires":[]},{"label":"Inspect the shrine named on the order","lines":[{"who":"ISA","mood":"neutral","text":"The destination may tell us what the sender intended."},{"who":"REI","mood":"neutral","text":"As long as we don't mistake a ritual site for proof of a crime."}],"flags":{},"to":"C09","requires":[]}],"lines":[]},"C06":{"id":"C06","title":"The loading shed","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The warehouse sat behind the western stables. From outside, they could hear two guards arguing about dice. Through a broken board, Isa spotted the stolen cart's blue-painted axle among stacked grain and cloth. A third guard patrolled the overhead loft."},{"who":"ISA","mood":"neutral","text":"Tobin wasn't mistaken. That's his father's cart."},{"who":"REI","mood":"neutral","text":"And the side window has an alarm glyph. We have options."},{"who":"NARRATION","mood":"neutral","text":"Athena tucked herself beneath the window and looked up at Isa as though awaiting instructions."}],"flags":{},"to":"C10"},"C07":{"id":"C07","title":"Decision handoff","bg":"VILLAGE","kind":"scene","lines":[],"flags":{},"to":"D16"},"C08":{"id":"C08","title":"The archive's lunar records","bg":"ARCHIVE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Bellhaven's archive was a tall, sunlit hall crowded with books, brass instruments, rolling ladders, and blue-and-gold stained glass. Rei stood still for a long, happy moment."},{"who":"REI","mood":"happy","text":"Wonderful."},{"who":"ISA","mood":"annoyed","text":"It's a room full of books."},{"who":"REI","mood":"smug","text":"And you claim to love me."},{"who":"ISA","mood":"laugh","text":"I didn't say I was going to burn it down!"},{"who":"NARRATION","mood":"neutral","text":"In the lunar records, a diagram showed a ring of hooked lines surrounding a sealed vessel. It was a safety ward designed to contain corrupted moonlight, not create it."},{"who":"REI","mood":"neutral","text":"This emblem is associated with containment. If the chest bears a similar design, its contents could become dangerous if released."},{"who":"ISA","mood":"neutral","text":"Then we keep it closed until we're ready to protect everyone around us."},{"who":"REI","mood":"happy","text":"Exactly."}],"flags":{"ward_understood":true,"archive_visited":true},"to":"C11"},"C09":{"id":"C09","title":"The abandoned sanctuary","bg":"SHRINE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Beyond the village fields, an old lunar shrine stood among pale stones in the evening moonlight. Vines wound around cracked columns; a broken crescent lay carved into an altar. Beneath a layer of moss, fresh boot prints marked the steps."},{"who":"ISA","mood":"neutral","text":"The Goddess was worshipped here. I can feel the old blessing in the stones."},{"who":"REI","mood":"neutral","text":"And recent visitors. Look at the mud."},{"who":"NARRATION","mood":"neutral","text":"A small cavity in the altar matched the dimensions Tobin's father had described. The engraved border resembled the symbol on the chest's shipment order."},{"who":"ISA","mood":"confused","text":"This is where the box was meant to go."},{"who":"REI","mood":"neutral","text":"Probably. But we don't know whether the sender wanted to restore the altar or misuse it."},{"who":"ISA","mood":"sad","text":"This place has been neglected so long."},{"who":"REI","mood":"neutral","text":"We can change that once we know what we're dealing with."}],"flags":{"shrine_examined":true,"altar_socket_found":true},"to":"C11"},"D17":{"id":"D17","title":"Warehouse entry","bg":"VILLAGE","kind":"choice","options":[{"label":"Disarm the window glyph and slip in","lines":[{"who":"REI","mood":"neutral","text":"The ward was installed poorly. I'll unwind it; Isa, watch the guards."},{"who":"ISA","mood":"smug","text":"I prefer tasks where I can judge strangers silently."},{"who":"REI","mood":"laugh","text":"A rare opportunity."}],"flags":{"stealth_success":true},"to":"C12","requires":[]},{"label":"Signal the captain's patrol (if `guard_contacted=true`)","lines":[{"who":"CAPTAIN","mood":"stern","text":"We'll take the front. You identify the stolen cargo. Nobody touches the chest until I say so."},{"who":"ISA","mood":"neutral","text":"Agreed."}],"flags":{"guard_support":true},"to":"C12","requires":[]},{"label":"Distract the guards with a staged argument","lines":[{"who":"ISA","mood":"mad","text":"WHAT DO YOU MEAN YOU LOST OUR ENTIRE PURSE?!"},{"who":"REI","mood":"annoyed","text":"What? I—oh. YES. A TRAGEDY."},{"who":"NARRATION","mood":"neutral","text":"The guards emerge to watch the commotion while Athena noses open the side gate."}],"flags":{"distraction_success":true},"to":"C12","requires":[]},{"label":"Leave without confronting armed thieves","lines":[{"who":"ISA","mood":"sad","text":"The boy is safe. But I hate leaving the cargo here."},{"who":"REI","mood":"neutral","text":"Then we tell the captain what we found and proceed to Sarovar."}],"flags":{"tip_given":true},"to":"E3","requires":[]}],"lines":[]},"C10":{"id":"C10","title":"Decision handoff","bg":"WAREHOUSE","kind":"scene","lines":[],"flags":{},"to":"D17"},"C11":{"id":"C11","title":"More than a rumor","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Armed with records from the archive or the shrine's measurements, Isa and Rei knew the stolen chest was likely connected to lunar containment. That still left the chest itself somewhere in the thieves' possession."},{"who":"ISA","mood":"neutral","text":"Then we know what to look for, and why not to open it recklessly."},{"who":"REI","mood":"neutral","text":"We can still decide to leave it sealed with the captain, or try to recover it before the buyer arrives."}],"flags":{},"to":"C13"},"C12":{"id":"C12","title":"The stolen cart","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The warehouse interior was dim, full of canvas-draped crates and ropes hanging from the loft. Tobin's father's cart stood near the rear wall. Isa lifted a folded blanket from the cargo bed and uncovered a square iron chest bound with silver bands."},{"who":"ISA","mood":"neutral","text":"Found it."},{"who":"REI","mood":"neutral","text":"Do not open it. Not here."},{"who":"NARRATION","mood":"neutral","text":"The chest was cold enough to frost the edge of the blanket. Violet light threaded around its lock. From beyond the doors came approaching footsteps and a harsh laugh."},{"who":"BANDIT","mood":"normal","text":"Check the wagon! The buyer wants that box before sunset."},{"who":"ISA","mood":"angry","text":"So there is a buyer."},{"who":"REI","mood":"neutral","text":"We can carry it out while they're distracted, or confront them now with proof of theft."}],"flags":{"chest_found":true},"to":"C14"},"C13":{"id":"C13","title":"Return to the warehouse or leave it to the guards","bg":"VILLAGE","kind":"scene","lines":[],"flags":{},"to":"C15"},"D18":{"id":"D18","title":"What to do with the chest","bg":"VILLAGE","kind":"choice","options":[{"label":"Extract it without opening the seal","lines":[{"who":"ISA","mood":"neutral","text":"We're taking it. Carefully."},{"who":"REI","mood":"neutral","text":"I'll keep the binding from moving."},{"who":"NARRATION","mood":"neutral","text":"They remove the chest while the thieves search another storeroom."}],"flags":{"chest_recovered":true},"to":"C19","requires":[]},{"label":"Confront the thieves with evidence","lines":[{"who":"ISA","mood":"angry","text":"STEP AWAY FROM THE CART! IT BELONGS TO TOBIN'S FAMILY!"},{"who":"BANDIT","mood":"normal","text":"And who are you supposed to be?"},{"who":"REI","mood":"smug","text":"People with excellent records of your crime and rapidly diminishing patience."},{"who":"NARRATION","mood":"neutral","text":"The gang's leader rushes to seize the chest; Rei contains him in a spell long enough for the party to escape with it."}],"flags":{"chest_recovered":true,"evidence":true},"to":"C19","requires":[]},{"label":"Grab only the ordinary goods and retreat","lines":[{"who":"ISA","mood":"sad","text":"I want to bring the boy's supplies home. We can't carry everything with that thing glowing."},{"who":"REI","mood":"neutral","text":"Then we'll report the box's location to the captain."}],"flags":{"supplies_returned":true},"to":"E3","requires":[]}],"lines":[]},"C14":{"id":"C14","title":"Decision handoff","bg":"WAREHOUSE","kind":"scene","lines":[],"flags":{},"to":"D18"},"D19":{"id":"D19","title":"Optional research detour (C11)","bg":"VILLAGE","kind":"choice","options":[{"label":"Pursue the chest at the warehouse","lines":[{"who":"ISA","mood":"neutral","text":"We shouldn't let those men sell it to someone who knows how to misuse it."},{"who":"REI","mood":"neutral","text":"Agreed. We go in prepared."}],"flags":{},"to":"C06","requires":[]},{"label":"Hand the clues to the captain and leave","lines":[{"who":"CAPTAIN","mood":"neutral","text":"I'll have the shrine and the warehouse watched. You've done enough to justify an investigation."},{"who":"ISA","mood":"sad","text":"I wish that felt like enough."},{"who":"REI","mood":"neutral","text":"Sometimes it has to be."}],"flags":{},"to":"E3","requires":[]}],"lines":[]},"C15":{"id":"C15","title":"Decision handoff","bg":"VILLAGE","kind":"scene","lines":[],"flags":{},"to":"D19"},"C16":{"id":"C16","title":"A cold little moon","bg":"SHRINE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"By the time they reached the old lunar sanctuary, evening had settled over the fields. They placed the still-sealed chest on the altar beneath the moon. The stone markings and silver fittings glowed faintly together."},{"who":"ISA","mood":"sad","text":"It’s her. Not all of her, but something of the Goddess is inside."},{"who":"REI","mood":"neutral","text":"And a binding is keeping it separate from the world. We need to understand that seal before opening anything."},{"who":"NARRATION","mood":"neutral","text":"A violet pulse moved through the metal and faded. Athena lay quietly at the foot of the altar."}],"flags":{"chest_recovered":true},"to":"C17"},"D20":{"id":"D20","title":"How should we proceed with the sealed lunar reliquary?","bg":"SHRINE","kind":"choice","options":[{"label":"Carefully examine and stabilize the seal","lines":[{"who":"REI","mood":"neutral","text":"The altar's pattern matches the exterior ward. I'll reinforce it while you listen for the Goddess's resonance."},{"who":"ISA","mood":"neutral","text":"I'll tell you if anything changes."},{"who":"NARRATION","mood":"neutral","text":"Together they isolate a fragment of corrupted moonlight without releasing it. The silver stone flickers like a star beneath dark water."}],"flags":{"fragment_identified":true,"fragment_contained":true},"to":"C18","requires":["ward_understood=true"]},{"label":"Keep the chest sealed and seek a custodian","lines":[{"who":"ISA","mood":"neutral","text":"We have no right to endanger the town just because we're curious."},{"who":"REI","mood":"happy","text":"That's a good call."},{"who":"NARRATION","mood":"neutral","text":"They return it to the captain with instructions not to break the ward."}],"flags":{"chest_secured":true},"to":"E3","requires":[]},{"label":"Break the seal without understanding it","lines":[{"who":"ISA","mood":"neutral","text":"I can try to force the magic apart."},{"who":"REI","mood":"annoyed","text":"You can, but it's a terrible experiment. Get behind my ward first."},{"who":"NARRATION","mood":"neutral","text":"A violent pulse breaks the outer clasp. Rei contains the burst, but the fragment goes unstable; its intact resonance is lost."},{"who":"ISA","mood":"sad","text":"We were so close."},{"who":"REI","mood":"neutral","text":"And still alive. We learn and move."}],"flags":{"fragment_damaged":true},"to":"E3","requires":[]},{"label":"Study the altar's engraving first","lines":[{"who":"REI","mood":"neutral","text":"The carving is an instruction, not decoration. We can read it before touching the chest."},{"who":"ISA","mood":"neutral","text":"Do that."},{"who":"NARRATION","mood":"neutral","text":"The party recognizes the ring as a protective structure."}],"flags":{"ward_understood":true},"to":"C17","requires":["!ward_understood","!shrine_examined"]}],"lines":[]},"C17":{"id":"C17","title":"Decision handoff","bg":"SHRINE","kind":"scene","lines":[],"flags":{},"to":"D20"},"C18":{"id":"C18","title":"A warning from the wounded moon","bg":"SHRINE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The fragment floated within Rei's ward, a small piece of silver light shot through with hair-thin violet cracks. Isa reached toward it and stopped a finger's width away. There was no voice, only a desperate sensation of light being pulled in opposite directions."},{"who":"ISA","mood":"cry","text":"She can't hold herself together forever."},{"who":"REI","mood":"neutral","text":"No. But look at the fracture. Something has been extracting energy from it. This was contained because it was already dangerous."},{"who":"ISA","mood":"sad","text":"The Archmage may be gathering pieces of what he broke."},{"who":"REI","mood":"neutral","text":"He may be. We have a clue, not the full plan. That is still more than we had yesterday."},{"who":"ISA","mood":"neutral","text":"Then we follow it to Sarovar."},{"who":"REI","mood":"happy","text":"Together."},{"who":"NARRATION","mood":"neutral","text":"A faint reflection of the Moon Goddess appeared across the shrine pool, no more than an outline among the ripples. It vanished when the fragment settled. Rei sealed the reliquary again, this time with the fragment stabilized inside."}],"flags":{"fragment_contained":true,"lunar_lead":true},"to":"E5"},"E1":{"id":"E1","title":"HEROES OF BELLHAVEN","bg":"VILLAGE","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"By sunset the town guard had locked the warehouse, seized the false maps, and returned the stolen goods. The square was noisy with relief. Shopkeepers who had whispered behind shutters now argued openly about who should provide supper for their unexpected champions."},{"who":"CAPTAIN","mood":"neutral","text":"You gave us the proof and helped end the operation. Bellhaven owes you a debt."},{"who":"ISA","mood":"happy","text":"Pay it by making sure the next frightened shopkeeper knows someone will listen."},{"who":"CAPTAIN","mood":"stern","text":"You have my word."},{"who":"REI","mood":"smug","text":"An admirable speech. Very few threats, considering the speaker."},{"who":"ISA","mood":"annoyed","text":"I CAN STILL THREATEN YOU."},{"who":"REI","mood":"laugh","text":"There it is."},{"who":"NARRATION","mood":"neutral","text":"Athena accepted a treat from the grateful baker. Isa and Rei took a trustworthy map and enough food to continue toward Sarovar. The wounded moon was still waiting; Bellhaven, at least, would see another peaceful morning."}],"flags":{},"to":null},"E2":{"id":"E2","title":"THE HAMHAM SPECIAL","bg":"SHOP","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"Back at Mopsy’s shop, the recovered ingredients were safely behind the counter. The bandit leader had been taken to the guardhouse, and the captain was cataloguing the stolen goods. Mopsy was celebrating as though she had just sold out a concert."},{"who":"MOPSY","mood":"excited","text":"MOPSY HAMHAM! ONE! BANDITS! ZERO!"},{"who":"REI","mood":"smug","text":"At least the bandit survived the encore."},{"who":"ISA","mood":"laugh","text":"And her shop is still standing. For the moment."},{"who":"NARRATION","mood":"neutral","text":"The door swung open. Mopsy’s landlord—an impeccably dressed leopard woman—stared at the thin plume of smoke leaking from a forgotten potion on the workbench."},{"who":"LANDLORD","mood":"angry","text":"MOPSY HAMHAM! WHY IS THERE SMOKE COMING OUT OF MY BUILDING?"},{"who":"MOPSY","mood":"excited","text":"A SUCCESSFUL CRIME-PREVENTION SHOWCASE!"},{"who":"LANDLORD","mood":"angry","text":"AND YOU STILL OWE ME THREE MONTHS’ RENT!"},{"who":"MOPSY","mood":"annoyed","text":"AND YOU STILL OWE ME SUPPORT FOR MY ARTISTIC VISION!"},{"who":"ISA","mood":"laugh","text":"I love her."},{"who":"REI","mood":"laugh","text":"She is going to be spectacular in court."},{"who":"NARRATION","mood":"neutral","text":"Mopsy performed an imaginary encore bow, then handed Isa two emergency tonics, Rei a signed photograph and Athena a glitter-covered biscuit. Rei inspected the biscuit before Athena was allowed near it."}],"flags":{},"to":null},"E3":{"id":"E3","title":"A NARROW ESCAPE","bg":"ROAD","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"Bellhaven's lanterns disappeared behind the hills. The party had survived, kept most of its resources, and gained whatever clues it had actually earned. But they had not personally ended the town's troubles."},{"who":"ISA","mood":"sad","text":"I hate leaving when people are still frightened."},{"who":"REI","mood":"neutral","text":"So do I. I simply show it differently."},{"who":"ISA","mood":"confused","text":"You do?"},{"who":"REI","mood":"neutral","text":"Of course. I don't enjoy injustice. I just know we can't fight everything before we reach Sarovar."},{"who":"ISA","mood":"neutral","text":"You could say that more often."},{"who":"REI","mood":"smug","text":"Then you'd have fewer reasons to yell at me."},{"who":"ISA","mood":"annoyed","text":"OH, YOU WOULD LOVE THAT."},{"who":"REI","mood":"laugh","text":"Actually, I'd miss it."},{"who":"NARRATION","mood":"neutral","text":"Athena trotted ahead, her cloak catching the last gold of daylight. Beyond the ridge lay the road to the Land of the Dead."}],"flags":{},"to":null},"E4":{"id":"E4","title":"HIGHWAY ROBBERY","bg":"ROAD","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"By the time the three companions escaped the bandits, their packs had been emptied and their coin purse was almost weightless. The road had grown quiet. Isa had not."},{"who":"ISA","mood":"mad","text":"THAT MAN SMILED RIGHT AT ME WHILE SELLING US A TRAP!"},{"who":"REI","mood":"neutral","text":"Fraudsters are often pleasant during the purchase."},{"who":"ISA","mood":"mad","text":"AND YOU KNEW SOMETHING WAS WRONG!"},{"who":"REI","mood":"smug","text":"I did mention the road was suspicious."},{"who":"ISA","mood":"annoyed","text":"I AM AWARE OF WHAT YOU MENTIONED."},{"who":"REI","mood":"laugh","text":"It's a comfort to know we're communicating."},{"who":"NARRATION","mood":"neutral","text":"Athena sneezed and dropped the last sausage wrapper at their feet."},{"who":"REI","mood":"confused","text":"Was that our dinner?"},{"who":"ISA","mood":"smug","text":"You see? Now you're emotional."},{"who":"NARRATION","mood":"neutral","text":"They continued north with lighter packs and a hard lesson about charming strangers."}],"flags":{},"to":null},"E5":{"id":"E5","title":"THE MOON'S WARNING","bg":"SHRINE","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"The shrine was still except for the ripple of silver in its reflecting pool. Inside the sealed reliquary, a wounded fragment of moonlight pulsed steadily beneath Rei's reinforcing ward. For the first time, they had something tangible that might explain the Goddess's fading strength."},{"who":"ISA","mood":"sad","text":"She's scattered into pieces. I could feel how hard it was for that light to hold together."},{"who":"REI","mood":"neutral","text":"We know one fragment was being moved by people connected to this trafficking network. We don't know yet who ordered it—or why."},{"who":"ISA","mood":"neutral","text":"But Sarovar may have answers."},{"who":"REI","mood":"happy","text":"Yes. And now we can ask better questions."},{"who":"ISA","mood":"smug","text":"You do love questions."},{"who":"REI","mood":"smug","text":"Especially the ones you answer before I finish asking."},{"who":"NARRATION","mood":"neutral","text":"Isa smiled through the last of her tears. Athena rested her head against her knee. High overhead, the broken moon glimmered above the stone arches, and the path toward Sarovar seemed both more dangerous and more necessary."}],"flags":{},"to":null},"E6":{"id":"E6","title":"FAMOUS LAST WORDS","bg":"WAREHOUSE","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy's eyes widened when the unstable bottle's stopper turned."},{"who":"MOPSY","mood":"scared","text":"WAIT! THAT ONE HAS NO STABILIZER!"},{"who":"REI","mood":"scared","text":"PUT IT DOWN. NOW."},{"who":"ISA","mood":"confused","text":"Why is it getting brighter?"},{"who":"NARRATION","mood":"neutral","text":"The bottle answered with a flash of impossible white light. The warehouse vanished in a puff of spectacularly bad decisions."}],"flags":{},"to":null},"A24":{"id":"A24","title":"The intercepted message","bg":"VILLAGE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Isa distracted the courier with a loudly invented argument about misplaced parcels. While he turned, Rei lifted the folded note from the courier’s belt with a nearly invisible thread of magic. They moved away before unfolding it."},{"who":"REI","mood":"neutral","text":"It names our departure time, the false shortcut at Willowpass, and a payment to be collected when we arrive."},{"who":"ISA","mood":"angry","text":"So they’re selling travelers into an ambush. We can show this to the captain, but I want to know what else is in that warehouse."},{"who":"REI","mood":"neutral","text":"We have a lead, not a ledger. We’ll have to find that separately."}],"flags":{},"to":"A14"},"B25":{"id":"B25","title":"An offer Mopsy can accept","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Before approaching the warehouse, Isa and Rei returned to Mopsy’s shop. They had asked questions earlier, but had never promised to recover her things or invited her along."},{"who":"ISA","mood":"neutral","text":"We found a lead to your stolen supplies. You don’t have to come, but you deserve to know what we’re doing."},{"who":"MOPSY","mood":"confused","text":"You’re actually going? After all that serious captain business?"},{"who":"REI","mood":"neutral","text":"We are. Would you rather accompany us, or have us send the guard captain back with news?"}],"flags":{},"to":"D21"},"D21":{"id":"D21","title":"Does Mopsy accompany you?","bg":"SHOP","kind":"choice","options":[{"label":"Invite Mopsy to help recover the stolen crate","lines":[{"who":"ISA","mood":"happy","text":"Come with us, if you want. We’ll stay together."},{"who":"MOPSY","mood":"excited","text":"MY SHOP! MY SUPPLIES! MY COMEBACK TOUR!"},{"who":"REI","mood":"neutral","text":"One mission at a time."}],"flags":{"mopsy_helped":true,"mopsy_accompanies":true,"mopsy_trust":1},"to":"B09","requires":[]},{"label":"Let the captain take the warehouse from here","lines":[{"who":"ISA","mood":"neutral","text":"You’ve done enough today. We’ll give the guard captain our evidence."},{"who":"MOPSY","mood":"neutral","text":"Then I’m trusting you to tell him exactly what was taken."}],"flags":{"guard_contacted":true},"to":"B15","requires":[]}],"lines":[]},"E1B":{"id":"E1B","title":"HEROES OF BELLHAVEN","bg":"VILLAGE","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"By evening the guards had secured the stolen goods and arrested the bandit crew operating out of the warehouse. Mopsy’s supplies were returned, and merchants came forward with details of other threats. The captain promised to investigate every lead, including any suspicious transport records."},{"who":"CAPTAIN","mood":"neutral","text":"You gave us the proof we needed to act against these thieves."},{"who":"ISA","mood":"neutral","text":"Then make sure the next shopkeeper knows someone will listen."},{"who":"REI","mood":"smug","text":"An admirable speech. Very few threats, considering the speaker."},{"who":"ISA","mood":"mad","text":"I CAN STILL THREATEN YOU."},{"who":"REI","mood":"laugh","text":"There it is."},{"who":"NARRATION","mood":"neutral","text":"Bellhaven’s merchants offered the travelers provisions for the road. Mopsy waved so enthusiastically from her doorway that her landlord came out to check whether anything else was on fire."}],"flags":{},"to":null},"E4B":{"id":"E4B","title":"HIGHWAY ROBBERY","bg":"ROAD","kind":"ending","lines":[{"who":"NARRATION","mood":"neutral","text":"By the time the three companions left Bellhaven, the bandits had taken the money and provisions they demanded. Mopsy’s stolen goods remained inside the warehouse. They were alive, but Isa hardly looked relieved."},{"who":"ISA","mood":"mad","text":"He stole her supplies, then tried to charge us for giving them back!"},{"who":"REI","mood":"neutral","text":"An impressively dishonest business model."},{"who":"ISA","mood":"annoyed","text":"Stop making jokes."},{"who":"REI","mood":"neutral","text":"You’re right. We’ll give the captain every detail we saw."},{"who":"ISA","mood":"sad","text":"I hate that we couldn’t do more."},{"who":"REI","mood":"neutral","text":"Then we’ll remember that when we get another chance."},{"who":"NARRATION","mood":"neutral","text":"Athena nudged Isa’s hand. Isa scratched her ears and continued north with Rei."}],"flags":{},"to":null},"C19":{"id":"C19","title":"Destination beneath the blanket","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Inside the stolen delivery wagon, Rei lifted the sealed chest from beneath a blanket. A folded dispatch note slid out beside it. The paper named the destination: “Old Lunar Sanctuary, north of Bellhaven’s fields.” A little route map was attached."},{"who":"ISA","mood":"neutral","text":"There. Now we know where the chest was supposed to go."},{"who":"REI","mood":"neutral","text":"And we know the original seal is still intact. We can take it to the shrine without opening it here."},{"who":"NARRATION","mood":"neutral","text":"Before leaving, they placed a note for the captain identifying the stolen wagon, the warehouse and its remaining cargo, so Tobin’s father could recover his property."}],"flags":{"shrine_known":true},"to":"C16"},"B_GUARD_INTRO":{"id":"B_GUARD_INTRO","title":"A captain, properly introduced","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Near the stable gate, two Bellhaven guards were watching the warehouse. Isa approached and explained the theft. One sent for their commander."},{"who":"CAPTAIN","mood":"stern","text":"Captain of the Bellhaven Guard. Tell me what you know, and what you only suspect."},{"who":"REI","mood":"neutral","text":"Mopsy’s shipment was stolen. We’ve traced it here. We have not entered the building or recovered any ledger."},{"who":"CAPTAIN","mood":"neutral","text":"Good distinction. I can send two guards to secure the exit while you help identify the stolen property."},{"who":"ISA","mood":"neutral","text":"Then let’s do this carefully."}],"flags":{"guard_contacted":true},"to":"B13"},"D22":{"id":"D22","title":"How should we redesign Rei’s stabilizer?","bg":"SHOP","kind":"choice","options":[{"label":"Examine Mopsy’s original schematics","lines":[{"who":"REI","mood":"neutral","text":"We need to understand her design before we try again."}],"flags":{"replacement_researched":true},"to":"B_R1","requires":[]},{"label":"Ask Mopsy about her old stage equipment","lines":[{"who":"ISA","mood":"neutral","text":"Mopsy, did your stage lights ever need to handle this much energy?"},{"who":"MOPSY","mood":"excited","text":"OH! MY FAREWELL TOUR HAD AN ENTIRE WALL OF ARCANE DIMMERS!"}],"flags":{"stage_idea":true},"to":"B_R2","requires":[]},{"label":"Insist on using the cracked prototype anyway","lines":[{"who":"REI","mood":"neutral","text":"No. We already know it fails under pressure. If you insist, we will have to start again after it breaks."}],"flags":{"reckless_attempt":true},"to":"B_R3","requires":[]}],"lines":[]},"B_R1":{"id":"B_R1","title":"The missing function","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The three sifted through ink-smeared pages, rehearsal notes, and a diagram Mopsy had folded inside an old concert program. The original crystal was designed with two chambers."},{"who":"REI","mood":"neutral","text":"There. A second channel carries surplus power away. I copied the shell but not the release path."},{"who":"ISA","mood":"neutral","text":"So we need an outlet, not a stronger cage."},{"who":"MOPSY","mood":"excited","text":"THAT’S WHAT MY OLD STAGE LIGHTS DID! I still have a dimmer wheel somewhere!"}],"flags":{},"to":"B_R4"},"B_R2":{"id":"B_R2","title":"The retired idol’s invention","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Mopsy dragged a trunk from beneath a display of idol figurines. Inside lay a dented concert-light dimmer and a faded backstage pass."},{"who":"MOPSY","mood":"smug","text":"I built it when the stage lights kept exploding during my third encore. Technically my second and a half encore."},{"who":"REI","mood":"surprised","text":"The circuitry diverts excess magic. That is exactly what my lattice lacks."},{"who":"ISA","mood":"neutral","text":"You two actually make a frighteningly competent team."}],"flags":{},"to":"B_R4"},"B_R3":{"id":"B_R3","title":"An avoidable setback","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The cracked prototype glowed unevenly. Rei extinguished the test before it could touch the potion; another section of the lattice fractured."},{"who":"REI","mood":"neutral","text":"That is the second failed prototype. We cannot pretend it passed."},{"who":"ISA","mood":"annoyed","text":"Fine. We do it properly this time."},{"who":"MOPSY","mood":"excited","text":"I KNOW WHERE WE CAN FIND A REAL PRESSURE REGULATOR! THE OLD TOUR TRUNK!"}],"flags":{},"to":"B_R4"},"B_R4":{"id":"B_R4","title":"An imperfect second rehearsal","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei fused the dimmer wheel to a new arcane lattice. Mopsy provided the original formula from memory. On the second test, the vessel held—but its pressure needle crept toward the danger mark."},{"who":"REI","mood":"neutral","text":"It is closer. We can direct the surplus into a grounding charm, or spread it across several smaller channels."},{"who":"MOPSY","mood":"excited","text":"One spectacular spotlight, or six tiny ones. I have experience with BOTH!"}],"flags":{},"to":"D23"},"D23":{"id":"D23","title":"How should they control the rising pressure?","bg":"SHOP","kind":"choice","options":[{"label":"Ground the excess energy through a ward","lines":[{"who":"ISA","mood":"neutral","text":"I’ll keep the grounding ward steady. Rei, adjust the release channel."},{"who":"REI","mood":"neutral","text":"The pressure is falling. Slowly this time."}],"flags":{"replacement_method":"ward"},"to":"B_R5","requires":[]},{"label":"Split the energy through Mopsy’s stage dimmer","lines":[{"who":"MOPSY","mood":"excited","text":"I CAN CALIBRATE SIX CHANNELS! Watch the lights!"},{"who":"REI","mood":"neutral","text":"They’re equalizing. Keep them steady."}],"flags":{"replacement_method":"dimmer"},"to":"B_R5","requires":[]},{"label":"Turn up the power to finish faster","lines":[{"who":"ISA","mood":"neutral","text":"That needle is already in the red."},{"who":"REI","mood":"neutral","text":"And turning it higher will not make the crystal safer."}],"flags":{"replacement_rushed":true},"to":"B_R6","requires":[]}],"lines":[]},"B_R6":{"id":"B_R6","title":"Another failed shortcut","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The pressure surged. Rei cut the arcane feed, while Isa caught the shattered test vial inside a shield. No one was hurt, but the workbench was coated in glitter."},{"who":"MOPSY","mood":"nervous","text":"That was an EXCELLENT demonstration of what not to do."},{"who":"REI","mood":"neutral","text":"We have enough information now. We choose a controlled method, or stop."}],"flags":{},"to":"D23"},"B_R5":{"id":"B_R5","title":"The replacement holds","bg":"SHOP","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"They tested a single drop again. For several long seconds the needle trembled. Then the surplus magic passed harmlessly through the release channel and the needle settled."},{"who":"REI","mood":"neutral","text":"Stable at test pressure. Now we test the full expected load—behind a shield."},{"who":"ISA","mood":"neutral","text":"I am not moving until we know it is safe."},{"who":"NARRATION","mood":"neutral","text":"The second test held. No crack, no pressure spike, and no uncontrolled release. Rei finally fitted the replacement into the locked potion socket."},{"who":"MOPSY","mood":"excited","text":"WE MADE IT THROUGH REHEARSAL! I WOULD LIKE EVERYONE TO APPLAUD!"},{"who":"REI","mood":"neutral","text":"It is a tested replacement, not a guarantee against careless handling."}],"flags":{"stable_potion":true,"replacement_built":true},"to":"B09"},"D24":{"id":"D24","title":"How should we trace the stolen stabilizing crystal?","bg":"WAREHOUSE","kind":"choice","options":[{"label":"Compare the warehouse ledger with the shipping note","lines":[{"who":"REI","mood":"neutral","text":"The timestamps may tell us when it was moved."}],"flags":{"warehouse_ledger_examined":true},"to":"B_W1","requires":[]},{"label":"Follow the marks toward the locked upper storeroom","lines":[{"who":"ISA","mood":"neutral","text":"Someone dragged something heavy up those steps. Let’s take a look."}],"flags":{"warehouse_tracks_followed":true},"to":"B_W2","requires":[]},{"label":"Question the lookout without alerting the bandits","lines":[{"who":"ISA","mood":"neutral","text":"If we can speak to him quietly, we may not need to break anything."}],"flags":{"warehouse_lookout_questioned":true},"to":"B_W3","requires":[]}],"lines":[]},"B_W1":{"id":"B_W1","title":"A falsified shipping order","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Rei compared the torn ledger with the label on Mopsy’s crate. The handwriting changed midway down the page. Someone had added a separate order for a small enchanted stone."},{"who":"REI","mood":"neutral","text":"They were told to hold the crystal for a buyer. The delivery mark says upper storeroom—not the main desk."},{"who":"MOPSY","mood":"nervous","text":"Then that is where we go. Quietly, ideally."}],"flags":{"buyer_clue":true,"evidence":true},"to":"B_W4"},"B_W2":{"id":"B_W2","title":"The room above the loading floor","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The scratches ended at a chained door. Beside it lay a discarded strip of Mopsy’s bright blue packing ribbon, caught beneath a cartwheel."},{"who":"ISA","mood":"neutral","text":"That is her ribbon. They carried the crate up here."},{"who":"REI","mood":"neutral","text":"And locked it after. We need to open this without bringing the whole warehouse down on us."}],"flags":{"warehouse_upper_located":true},"to":"B_W4"},"B_W3":{"id":"B_W3","title":"The lookout knows more","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The lookout relaxed when Isa pretended to be collecting an overdue delivery. At the mention of an enchanted stone, his expression changed."},{"who":"BANDIT","mood":"neutral","text":"I was told not to touch that little crystal. Boss put it in the upstairs lockbox for some buyer."},{"who":"REI","mood":"smug","text":"Then we have a destination. Thank you for being unexpectedly helpful."},{"who":"NARRATION","mood":"neutral","text":"They slipped away before the lookout realized what he had said."}],"flags":{"buyer_clue":true},"to":"B_W4"},"B_W4":{"id":"B_W4","title":"A strongbox and footsteps","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The upper storeroom contained a chained strongbox. A stamped notice on its lid warned that the contents had been reserved for a buyer. Footsteps creaked below."},{"who":"MOPSY","mood":"neutral","text":"I can pick the lock. I used to lose my dressing-room key constantly."},{"who":"REI","mood":"neutral","text":"Or I can release the ward, but it might alert whoever placed it."},{"who":"ISA","mood":"neutral","text":"We have very little time."}],"flags":{},"to":"D25"},"D25":{"id":"D25","title":"How should the group open the strongbox?","bg":"WAREHOUSE","kind":"choice","options":[{"label":"Let Mopsy work the lock quietly","lines":[{"who":"MOPSY","mood":"smug","text":"My years of backstage emergencies have prepared me for this exact moment!"}],"flags":{"strongbox_opened":"quiet"},"to":"B_W5","requires":[]},{"label":"Have Rei unravel its arcane ward","lines":[{"who":"REI","mood":"neutral","text":"I can do it. But the ward will flicker, so be prepared."}],"flags":{"strongbox_opened":"magic"},"to":"B_W5","requires":[]},{"label":"Force the lock before the footsteps get closer","lines":[{"who":"ISA","mood":"angry","text":"We might not have time to be subtle."}],"flags":{"strongbox_opened":"force"},"to":"B_W6","requires":[]}],"lines":[]},"B_W6":{"id":"B_W6","title":"An alarm and a narrow window","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"The metal hinge snapped with a crash. A warning bell rang upstairs, followed by a shouted order from below."},{"who":"REI","mood":"neutral","text":"We have seconds. I’ll restrain the hinge while you collect the contents."},{"who":"ISA","mood":"neutral","text":"Mopsy, take the crystal. Go!"}],"flags":{"warehouse_alarm":true},"to":"B_W5"},"B_W5":{"id":"B_W5","title":"The stolen crystal, finally","bg":"WAREHOUSE","kind":"scene","lines":[{"who":"NARRATION","mood":"neutral","text":"Inside the strongbox, beneath a forged invoice and a buyer’s deposit, lay the stabilizing crystal in its velvet casing. The crystal was cold and intact. The bandits had guarded it for a reason."},{"who":"MOPSY","mood":"cry","text":"There you are. I thought they had broken you."},{"who":"REI","mood":"neutral","text":"We have the original now. The buyer’s invoice is evidence, and we still need to verify the seal before using it."},{"who":"ISA","mood":"neutral","text":"Then we test it and get out before someone finds us."}],"flags":{"original_recovered":true,"buyer_clue":true,"evidence":true},"to":"B20"}};
const portraits={"ISA":{"neutral":"data:image/webp;base64,","happy":"data:image/webp;base64,","excited":"data:image/webp;base64,","laugh":"data:image/webp;base64,","annoyed":"data:image/webp;base64,","angry":"data:image/webp;base64,","sad":"data:image/webp;base64,","cry":"data:image/webp;base64,","blush":"data:image/webp;base64,","confused":"data:image/webp;base64,","scared":"data:image/webp;base64,","smug":"data:image/webp;base64,"},"REI":{"neutral":"data:image/webp;base64,","happy":"data:image/webp;base64,","excited":"data:image/webp;base64,","laugh":"data:image/webp;base64,","annoyed":"data:image/webp;base64,","angry":"data:image/webp;base64,","sad":"data:image/webp;base64,","cry":"data:image/webp;base64,","blush":"data:image/webp;base64,","confused":"data:image/webp;base64,","scared":"data:image/webp;base64,","smug":"data:image/webp;base64,","surprised":"data:image/webp;base64,"},"BANDIT":{"neutral":"data:image/webp;base64,","normal":"data:image/webp;base64,","bombed":"data:image/webp;base64,"},"MAP VENDOR":{"neutral":"data:image/webp;base64,","nervous":"data:image/webp;base64,","smug":"data:image/webp;base64,"},"BANDIT MESSENGER":{"neutral":"data:image/webp;base64,","nervous":"data:image/webp;base64,","scared":"data:image/webp;base64,"},"BANDIT GUARDS":{"neutral":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"BELLHAVEN CAPTAIN":{"neutral":"data:image/webp;base64,","stern":"data:image/webp;base64,","surprised":"data:image/webp;base64,"},"TOBIN":{"neutral":"data:image/webp;base64,","happy":"data:image/webp;base64,","scared":"data:image/webp;base64,"},"TOBIN FATHER":{"neutral":"data:image/webp;base64,","worried":"data:image/webp;base64,","relieved":"data:image/webp;base64,"},"VILLAGE MOTHER":{"neutral":"data:image/webp;base64,","happy":"data:image/webp;base64,"},"MOPSY LANDLORD":{"neutral":"data:image/webp;base64,","angry":"data:image/webp;base64,","exasperated":"data:image/webp;base64,"},"MOPSY HAMHAM":{"happy":"data:image/webp;base64,","neutral":"data:image/webp;base64,","annoyed":"data:image/webp;base64,","angry":"data:image/webp;base64,","sad":"data:image/webp;base64,","excited":"data:image/webp;base64,","scared":"data:image/webp;base64,","nervous":"data:image/webp;base64,","confused":"data:image/webp;base64,","smug":"data:image/webp;base64,","laugh":"data:image/webp;base64,"},"ATHENA":{"happy":"data:image/webp;base64,","neutral":"data:image/webp;base64,","angry":"data:image/webp;base64,"}};
const backgrounds={"VILLAGE":"data:image/webp;base64,","SHOP":"data:image/webp;base64,","WAREHOUSE":"data:image/webp;base64,","ROAD":"data:image/webp;base64,","ARCHIVE":"data:image/webp;base64,","SHRINE":"data:image/webp;base64,"};
const frameImage='data:image/webp;base64,';
const narratorFrameImage='data:image/webp;base64,';
const dialogueWrap=$('mscDialogueWrap');
const elements={overlay:$('mscOverlay'),stage:$('mscStage'),background:$('mscBackdrop'),left:$('mscLeft'),right:$('mscRight'),pet:$('mscPet'),text:$('mscText'),speaker:$('mscSpeaker'),choices:$('mscChoices'),end:$('mscEnd'),hud:$('mscHud')};
$('mscDialogueFrame').src=frameImage;
let active=false, current=null, pages=[],pageIndex=0,queueGoto=null, pendingFlags=null, pendingEnding=false;
let currentText='',visibleChars=0,typingHandle=null,typingDone=true,transitCount=0;
let flags={};let coins=24,supplies=0; let selectedRoute='';
const moodAliases={sad:'cry',angry:'mad',confuse:'confused',normal:'neutral',surprised:'scared'};
const whoMap={'VENDOR':'MAP VENDOR','MOTHER':'VILLAGE MOTHER','CAPTAIN':'BELLHAVEN CAPTAIN','FATHER':'TOBIN FATHER','MESSENGER':'BANDIT MESSENGER','GUARD':'BANDIT GUARDS','LANDLORD':'MOPSY LANDLORD','MOPSY':'MOPSY HAMHAM','BANDIT':'BANDIT'};
const narratorNames=['NARRATION','WARNING'];
const statuses={};let nextTick=0;
function audioStop(){try{window.MoonlightSoundtrack?.suspendForStory?.();window.MoonlightSoundtrack?.setMode?.('story');}catch(_){}}
function audioRestore(){try{window.MoonlightSoundtrack?.resumeFromStory?.();window.MoonlightSoundtrack?.setMode?.('main');}catch(_){}}
function stopType(){if(typingHandle){clearInterval(typingHandle);typingHandle=null;}}
function reset(){stopType();flags={};coins=24;supplies=0;current=null;pages=[];pageIndex=0;queueGoto=null;pendingFlags=null;pendingEnding=false;typingDone=true;transitCount++;selectedRoute='';statuses.left=null;statuses.right=null;statuses.pet=null;
  for(const el of [elements.left,elements.right,elements.pet]){el.removeAttribute('src');el.classList.remove('msc-on','msc-jolt');}
  elements.end.classList.remove('msc-show');elements.choices.classList.remove('msc-open');elements.speaker.textContent='';elements.text.textContent='';}
function start(){reset();active=true;audioStop();
 try{if(screen.orientation?.lock && matchMedia('(pointer:coarse)').matches)Promise.resolve(screen.orientation.lock('landscape')).catch(()=>{});}catch(_ignored){}
elements.overlay.classList.add('msc-active');elements.stage.setAttribute('tabindex','-1');elements.stage.focus({preventScroll:true});$('moonLaunch')?.classList.add('hidden');goto('S01');}
function close(){active=false;reset();elements.overlay.classList.remove('msc-active');$('moonLaunch')?.classList.remove('hidden');audioRestore();}
function sceneIsAllowed(req){if(!req||req.length===0)return true;return req.every(expr=>{expr=expr.trim();if(!expr)return true;
 if(expr==='!ward_understood')return !flags.ward_understood;if(expr==='!shrine_examined')return !flags.shrine_examined;
 const match=expr.match(/^(!?)([\w_]+)(?:=(true|false|\d+))?$/);if(!match)return true;
 const v=match[3]==='true'?true:match[3]==='false'?false:match[3]!==undefined?Number(match[3]):true;
 return match[1]?!flags[match[2]]:flags[match[2]]===v;
 });}
function applyFlags(updates){if(!updates)return;for(const [k,v] of Object.entries(updates)){if(k==='coins_delta'){coins=Math.max(0,coins+Number(v));continue;}if(k==='supplies_delta'){supplies=Math.max(0,supplies+Number(v));continue;}flags[k]=v;if(k==='route')selectedRoute=v;if(k==='supplies')supplies=v;if(k==='coins')coins=v;} }
function setBackground(bg){const uri=backgrounds[bg]||backgrounds.VILLAGE;if(elements.background.dataset.src!==uri){elements.background.src=uri;elements.background.dataset.src=uri;} }
function hidePet(){elements.pet.classList.remove('msc-on');statuses.pet=null;}
function imageFor(who,mood){const name=whoMap[who]||who;const stock=portraits[name];if(!stock)return null;return stock[mood]||stock[moodAliases[mood]]||stock.neutral||Object.values(stock)[0]||null;}
function speakerSide(who){if(who==='ATHENA')return 'pet';if(who==='ISA')return 'left';return 'right';}
function presentActor(who,mood){if(narratorNames.includes(who))return;
 const side=speakerSide(who),el=elements[side],image=imageFor(who,mood);if(!image)return;
 const key=who+':'+mood; if(statuses[side]!==key){el.src=image;el.alt=who+' — '+mood;el.classList.add('msc-on');el.classList.remove('msc-jolt');void el.offsetWidth;el.classList.add('msc-jolt');statuses[side]=key;}
 if(side==='pet'){const tick=++nextTick;setTimeout(()=>{if(active&&tick===nextTick)hidePet();},3600);}
}
function updateHud(){const chapter=selectedRoute?' · Route '+selectedRoute:'';elements.hud.textContent='Coins: '+coins+' · Supplies: '+supplies+chapter+' · Decisions: '+Object.values(flags).filter(Boolean).length;}
function setPage(line){stopType();currentText=line.text||'';visibleChars=0;typingDone=false;
 const noName=narratorNames.includes(line.who); dialogueWrap.classList.toggle('msc-narration',noName);$('mscDialogueFrame').src=noName?narratorFrameImage:frameImage;
 elements.speaker.textContent=noName?'':line.who==='MOPSY'?'MOPSY HAMHAM':line.who==='VENDOR'?'CARTOGRAPHER':line.who==='CAPTAIN'?'GUARD CAPTAIN':line.who==='FATHER'?'TOBIN’S FATHER':line.who==='MOTHER'?'VILLAGE MOTHER':line.who;
 elements.text.textContent='';presentActor(line.who,line.mood);
 elements.text.style.removeProperty('font-size');
 if(noName){typingDone=true;visibleChars=currentText.length;elements.text.textContent=currentText;requestAnimationFrame(fitText);return;}
 const speed=linespeed(line);typingHandle=setInterval(()=>{visibleChars=Math.min(currentText.length,visibleChars+2);elements.text.textContent=currentText.slice(0,visibleChars);if(visibleChars>=currentText.length){stopType();typingDone=true;requestAnimationFrame(fitText);}},speed);
 requestAnimationFrame(fitText);
}
function linespeed(line){return 16;}
function fitText(){
 if(!active)return;
 const el=elements.text;
 // No clipping, no scrolling, no vertical jumping. Always fit the complete narration.
 const base=parseFloat(getComputedStyle(el).fontSize)||20;
 let size=base;const minimum=Math.min(13,base);
 for(let i=0;i<20&&el.scrollHeight>el.clientHeight+3&&size>minimum;i++){
   size=Math.max(minimum,size-0.65);el.style.setProperty('font-size',size+'px','important');
 }
}
function showPage(){if(!active)return;if(pageIndex<pages.length){setPage(pages[pageIndex]);return;}
 stopType();typingDone=true;elements.text.textContent=''; if(pendingFlags){applyFlags(pendingFlags);pendingFlags=null;updateHud();}
 if(queueGoto){const dest=queueGoto;queueGoto=null;goto(dest);return;}
 if(pendingEnding){pendingEnding=false;showEnding();return;}
 if(current&&current.kind==='choice'){showChoices();return;}
}
function advance(){if(!active||elements.choices.classList.contains('msc-open')||elements.end.classList.contains('msc-show'))return;
 if(!typingDone){stopType();typingDone=true;elements.text.textContent=currentText;requestAnimationFrame(fitText);return;}
 pageIndex++;showPage();}
function goto(key){if(!active)return;const node=sceneData[key];if(!node){console.error('Unknown story node',key);return;}
 current=node;pages=node.lines||[];pageIndex=0;queueGoto=null;pendingFlags=null;pendingEnding=false;elements.choices.classList.remove('msc-open');setBackground(node.bg);
 if(node.kind==='scene'){queueGoto=node.to||null;pendingFlags=node.flags||{};}
 if(node.kind==='ending'){pendingEnding=true;pendingFlags=node.flags||{};}
 if(!pages.length){showPage();}else showPage();updateHud();}
function optionAllowed(opt){if(current?.id==='D20'&&opt.label.startsWith('Carefully examine'))return !!(flags.ward_understood||flags.shrine_examined);if(!sceneIsAllowed(opt.requires))return false;
 if(opt.label.includes('tested stable')&&!flags.stable_potion)return false;
 if(opt.label.includes('Ignore warnings')&&!flags.unstable_potion)return false;
 if(current?.id==='D20'&&opt.label.startsWith('Carefully examine'))return !!(flags.ward_understood||flags.shrine_examined);
 if(current?.id==='D20'&&opt.label.startsWith('Study the altar'))return !(flags.ward_understood||flags.shrine_examined);
 if(current?.id==='D06'&&opt.label.includes('Bring the captain'))return !!(flags.guard_contacted||flags.messenger_note||flags.evidence);
 if(current?.id==='D17'&&opt.label.includes('Signal the captain'))return !!flags.guard_contacted;
 return true;}
function showChoices(){dialogueWrap.classList.add('msc-narration');$('mscDialogueFrame').src=narratorFrameImage;const opts=(current.options||[]).filter(optionAllowed);elements.choices.replaceChildren();elements.choices.classList.add('msc-open');elements.speaker.textContent='';elements.text.textContent=current.title;elements.text.style.removeProperty('font-size');
 for(const [i,opt] of opts.entries()){
  const btn=document.createElement('button');btn.type='button';btn.className='mscChoice';btn.textContent=(i+1)+'. '+opt.label.replace(/\*/g,'');btn.addEventListener('click',ev=>{ev.stopPropagation();choose(opt);});elements.choices.appendChild(btn);
 }
 if(!opts.length){console.warn('No unlocked choices',current.id);const fallback=document.createElement('button');fallback.className='mscChoice';fallback.textContent='Continue the journey';fallback.onclick=()=>goto('E3');elements.choices.appendChild(fallback);}
}
function choose(opt){elements.choices.classList.remove('msc-open');pages=opt.lines||[];pageIndex=0;pendingFlags=opt.flags||{};queueGoto=opt.to||'E3';

 if(opt.to==='E6')elements.text.setAttribute('aria-live','assertive');else elements.text.setAttribute('aria-live','off');
 showPage();}
function showEnding(){const node=current;if(!node||node.kind!=='ending')return;
 const labels={E1:'HEROES OF BELLHAVEN',E1B:'HEROES OF BELLHAVEN',E2:'THE HAMHAM SPECIAL',E3:'A NARROW ESCAPE',E4:'HIGHWAY ROBBERY',E4B:'HIGHWAY ROBBERY',E5:'THE MOON’S WARNING',E6:'FAMOUS LAST WORDS'};
 $('mscEndTitle').textContent=(node.id==='E6'?'GAME OVER · ':'CHAPTER ONE · ')+(labels[node.id]||node.title);
 $('mscEndText').textContent=node.id==='E6'?'An unstable potion was deliberately unsealed despite clear warnings. Your adventure starts again from Bellhaven.':'The road to Sarovar continues. Your choices have shaped what the party learned, saved, and lost.';
 elements.end.classList.add('msc-show');
 if(node.id==='E6'){const marker=++transitCount;setTimeout(()=>{if(active&&marker===transitCount)start();},4000);}
}
function testChoices(){if(!active)return;stopType();if(current?.kind==='scene'&&current.to){goto(current.to);return;}if(current?.kind==='choice'){pages=[];showChoices();return;}advance();}
// Do not touch Duel Mode or the independent narrated prologue.
$('mscExit').addEventListener('click',e=>{e.stopPropagation();close();});$('mscRestart').addEventListener('click',e=>{e.stopPropagation();start();});$('mscSkip').addEventListener('click',e=>{e.stopPropagation();testChoices();});$('mscEndAgain').addEventListener('click',e=>{e.stopPropagation();start();});$('mscEndMenu').addEventListener('click',e=>{e.stopPropagation();close();});
$('mscContinue').addEventListener('click',e=>{e.stopPropagation();advance();});elements.stage.addEventListener('click',e=>{if(!active||e.target.closest('button')||elements.choices.classList.contains('msc-open'))return;advance();});elements.overlay.addEventListener('click',e=>{if(e.target===elements.overlay&&active)advance();});
document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){close();return;}if((e.key==='Enter'||e.key===' ')&&e.target.tagName!=='BUTTON'){e.preventDefault();advance();}});
window.MoonStoryChapter={start,exit:close,openFromPrologue:start,chapterChoices:21,endingCount:6,getState:()=>({...flags}),getScene:()=>current?.id,sceneCount:Object.keys(sceneData).length};
})();
